-- Additive import from morfars master v125 and Gerd branch sibling/godparent source.
-- Existing array content is preserved; uncertain and conflicting facts remain explicitly marked.
begin;

create or replace function pg_temp.append_unique_jsonb_array(base jsonb, additions jsonb)
returns jsonb
language sql
immutable
as $$
  select coalesce(jsonb_agg(value order by first_position), '[]'::jsonb)
  from (
    select value, min(position) as first_position
    from (
      select value, ordinality::bigint as position
      from jsonb_array_elements(coalesce(base, '[]'::jsonb)) with ordinality
      union all
      select value, 1000000 + ordinality::bigint as position
      from jsonb_array_elements(coalesce(additions, '[]'::jsonb)) with ordinality
    ) combined
    group by value
  ) unique_values;
$$;

create or replace function pg_temp.merge_archive_arrays(base jsonb, additions jsonb)
returns jsonb
language plpgsql
as $$
declare
  result jsonb := coalesce(base, '{}'::jsonb);
  key_name text;
begin
  foreach key_name in array array['aliases','relatedPersonIds','facts','story','timeline','sources','uncertainties','parents','children','images'] loop
    if additions ? key_name then
      result := jsonb_set(result, array[key_name], pg_temp.append_unique_jsonb_array(result->key_name, additions->key_name), true);
    end if;
  end loop;
  return result;
end;
$$;

-- Existing person: arvid_svensson
update public.people set content = pg_temp.merge_archive_arrays(content, '{"facts":[["Begravd","1785-02-24"],["Hemman","1/2 kronohemman nr 5 Munkaskog"],["Civilstånd vid död","Änkling"],["Ålder i dödnotis","64 år, 3 månader, 11 dagar"],["Dödsorsak","Tolkad som hufvudsjuka / huvudvärkssjuka"],["Bouppteckning","1785-03-22"],["Barn","Hans, Anders, Inger, Bengt, Nils och Bengta"],["Barnens mödernearv","Bouppteckningens gravationer hänvisar till barnens arv efter Elin Bengtsdotter och en äldre handling/skiftesuppgift från 1779."],["Personer vid bouppteckningen","Nils Hallongren samt Thore Johansson i Sotta och Sven Bengtsson i Munkaskog förekommer i rättsliga eller värderande roller; ingen släktskap antas."],["Lokalt ekonomiskt nätverk","Lars Svensson i Tagebo och andra lokala namn förekommer bland skulder och fordringar utan att vara bevisade släktingar."]],"story":["Arvid Svensson, även skriven Arfvid Svensson, är Bengtas far enligt födelsenotisen 1774 och är ytterligare stärkt genom bouppteckningen 1785.","Bouppteckningen efter Arfvid Svensson upprättades 22 mars 1785 och gäller mannen på 1/2 kronohemman nr 5 Munkaskog. Den anger barnen med åldrar och binder Bengta till rätt familj och plats.","Boet visar ett etablerat men inte rikt bondehushåll med gårdsdrift, kreatur, textilier, hushållsföremål, bibel och postilla, men även skulder och gravationer.","Bouppteckningen visar att flera barn var minderåriga när Arvid dog. Eftersom Elin redan hade avlidit 1779 blev Bengta föräldralös omkring tio års ålder.","Posten om barnens mödernearv är en viktig indirekt källa till Elins familj. Den nämner Hans, Anders, Bengt, Nils, Inger och Bengta och stärker bedömningen att Elin var mor till hela barnaskaran."],"timeline":[["ca 1720-11","Född, beräknat från ålder i dödnotis."],["1774-10-20","Dottern Bengta föds i Munkaskog."],["1785-02-22","Dör som änkling i Munkaskog, Sven Börges/Sven Börjes gård."],["1785-02-24","Begravs."],["1785-03-22","Bouppteckning upprättas efter Arfvid Svensson."]],"sources":["Släktforskningslogg 2026-07-06, syskon och faddrar: fördjupad läsning av Arvid Svenssons bouppteckning 1785-03-22."],"uncertainties":["Exakta belopp och enskilda namn i bouppteckningens skulder, fordringar och mödernearv behöver kontrolläsas innan de anges som säkra siffror eller släktrelationer."],"parents":[],"children":["hans_arfvidsson","anders_arfvidsson","inger_arfvidsdotter","bengt_arfvidsson","nils_arfvidsson","bengta_arvidsdotter"]}'::jsonb) where id = 'arvid_svensson';
-- Existing person: elin_bengtsdotter
update public.people set content = pg_temp.merge_archive_arrays(content, '{"facts":[["Begravd","1779-04-01"],["Civilstånd vid död","Gift"],["Make","Arfvid / Arvid Svensson"],["Ålder i dödnotis","46 år, 3 månader"],["Dödsorsak","Bröstsjuka"],["Koppling","Mor till Bengta Arvidsdotter"],["Mödernearv","Arvid Svenssons bouppteckning 1785 hänvisar till barnens mödernearv efter Elin och en handling från 1779."],["Motstridigt begravningsdatum","Webbplatsens tidigare familjeuppgift anger 1779-04-01. Syskon-/fadderfilen från 2026-07-06 anger 1779-04-11. Originalnotisen måste avgöra datumet."]],"story":["Elin Bengtsdotter är bekräftad som Bengtas mor i födelsenotisen 1774.","Dödnotisen anger henne som åboen Arfvid Svenssons hustru i Munkaskog, Sven Börges/Sven Börjes gård. Detta stärker familjegruppen i samma gårdsmiljö.","Elins eget ursprung är ännu inte löst. Nästa steg är att hitta vigseln med Arfvid eller spåra barnens födelsenotiser och faddrar.","Eftersom den aktuella bouppteckningsserien börjar 1781 fungerar posten om mödernearvet i Arvids bouppteckning som en indirekt ersättningskälla för en saknad eller förlorad handling efter Elin."],"timeline":[["ca 1732/1733","Född, beräknat från ålder i dödnotis."],["1774-10-20","Dottern Bengta föds."],["1779-03-28","Dör i Munkaskog, dödsorsak bröstsjuka."],["1779-04-01","Begravs."],["1779-04-11","Alternativt begravningsdatum i syskon-/fadderfilen. Den äldre publicerade uppgiften är 1779-04-01; konflikten är inte avgjord."]],"sources":["Släktforskningslogg 2026-07-06, syskon och faddrar: Elins dödnotis och mödernearv i Arvids bouppteckning."],"uncertainties":["Begravningsdatumet är motstridigt: 1 april respektive 11 april 1779. Båda bevaras tills originalbilden har kontrollästs."],"parents":[],"children":["hans_arfvidsson","anders_arfvidsson","inger_arfvidsdotter","bengt_arfvidsson","nils_arfvidsson","bengta_arvidsdotter"]}'::jsonb) where id = 'elin_bengtsdotter';
-- Existing person: bengt_arfvidsson
update public.people set content = pg_temp.merge_archive_arrays(content, '{"facts":[["Ålder 1785","16 år"],["Källa","Bouppteckning efter Arfvid Svensson 1785"],["Kommentar","Kan vara samma Bengt som tidigare nämnts som broder Bengt i husförhörsspår"],["Födelsenotis","Född och döpt 1768; exakta dagar behöver kontrolläsas i helsidan."],["Föräldrar i födelsenotisen","Arvid Svensson och Elin Bengtsdotter."],["Födelseplats","Lille Svensgård / Lilla Svensgård."],["Faddrar och nätverk","Bengt i Munkagården, Nils i Hermanslycka eller liknande, en osäkert läst Lars i Juteby/Sibbarp, Karin Larsdotter i Munkaskog och Inger Svensdotter i Munkagården."]],"story":["Bengt anges som 16-årig son i bouppteckningen efter Arfvid Svensson. Han kan vara relevant för tidigare spår där en broder Bengt nämns.","Födelsenotisen 1768 och bouppteckningen 1785 bekräftar tillsammans Bengt som son till Arvid Svensson och Elin Bengtsdotter. Platsen Lille Svensgård kan visa en flytt eller gårdskoppling före familjens senare poster i Munkaskog.","Fadderkretsen knyter notisen till Munkagården och Munkaskog, men de osäkra namn- och ortsläsningarna ska inte användas som bevisade släktrelationer."],"sources":["Tvååkers födelsebok 1768, enligt släktforskningsloggen 2026-07-06; exakt bild- och sidreferens återstår."],"uncertainties":["Bengts exakta födelse- och dopdatum samt flera fadder- och ortsläsningar behöver kontrolläsas i hela originaluppslaget."],"parents":["arvid_svensson","elin_bengtsdotter"],"children":[]}'::jsonb) where id = 'bengt_arfvidsson';
-- Existing person: nils_arfvidsson
update public.people set content = pg_temp.merge_archive_arrays(content, '{"facts":[["Ålder 1785","14 år"],["Källa","Bouppteckning efter Arfvid Svensson 1785"],["Kommentar","Möjlig koppling till tidigare Nils-spår i Munkaskog"],["Född","1771-07-01 i Munkaskog."],["Döpt","1771-07-02."],["Föräldrar i födelsenotisen","Arfvid Svensson och Elin Bengtsdotter."],["Faddrar och nätverk","Kierstin Bengtsdotter, klockaren Nils Ekman, Sven Svensson i Frättegården och Catharina Olofsdotter; flera ortsläsningar är osäkra."],["Möjligt Elin-spår","Kierstin Bengtsdotter kan höra till Elins släktnätverk, men relationen är inte bevisad."]],"story":["Nils anges som 14-årig son i bouppteckningen efter Arfvid Svensson. Detta ger tydligare kontext åt det tidigare Nils-spåret i Munkaskog.","Nils föds 1 juli 1771 och döps följande dag som son till Arfvid Svensson och Elin Bengtsdotter i Munkaskog. Åldern stämmer exakt med bouppteckningens uppgift om en 14-årig son i mars 1785.","Faddern Kierstin Bengtsdotter är ett viktigt spår kring Elins ursprung, men samma patronymikon räcker inte för att fastställa släktskap."],"timeline":[["1771-07-01","Föds i Munkaskog."],["1771-07-02","Döps."]],"sources":["Tvååkers födelsebok 1771, enligt släktforskningsloggen 2026-07-06; exakt bild- och sidreferens återstår."],"uncertainties":["Kierstin Bengtsdotters relation till Elin samt flera orter i fadderlistan är ännu inte klarlagda."],"parents":["arvid_svensson","elin_bengtsdotter"],"children":[]}'::jsonb) where id = 'nils_arfvidsson';
-- Existing person: harry_bengtsson
update public.people set content = pg_temp.merge_archive_arrays(content, '{"aliases":["Harry Bengtsson"],"facts":[["Födelseort","Klastorp"],["Maka","Karin Margit Johansson"],["Barn","Ingemar och Gerd Bengtsson"],["Föräldrar","Sven Adolf Bengtsson och Gertrud Persdotter"],["Källstatus","Födelsedatum och födelseort finns som arbetsuppgift; originalnotis ska dokumenteras"],["Arrende Valagården","Arrenderade Träslöv 5:7 av farbrodern Lars Emil Bengtsson 1958-04-01–1963-04-01."],["Arrendeavgift","900 kronor per år, betald halvårsvis."],["Brukningsvillkor","Fick använda lada och loge; skulle väl bruka jorden, återställa vall och rensa gränsdiket vartannat år."],["Jordägarens förbehåll","Lars Emil behöll Smedlyckan bakom ladan och svarade för byggnadsunderhållet."],["Motstridigt födelsedatum","Tidigare familjeuppgift anger 1916-12-22; två handskrivna släktblad anger 1916-12-18."],["Korsberg","Övertog gården 1954 och överlät den till sonen Hans Ingemar 1985 enligt familjeberättelsen."],["Valagården","Flyttade med Karin till släktgården 1985; överlåtelseformen behöver verifieras i fastighetsakter."]],"story":["Axel Harry Bengtsson föds 22 december 1916 i Klastorp och avlider 1998.","Den senaste morfarsfilen kopplar honom preliminärt till föräldrarna Sven Adolf Bengtsson och Gertrud Persdotter. Födelsenotisen 1916 är prioriterad nästa kontroll för att låsa föräldrarna i originalkälla.","Harry gifter sig med Karin Margit Johansson. Tillsammans får de barnen Ingemar och Gerd Bengtsson.","Ett originalkontrakt från 1958 visar att Harry, då lantbrukare i Klastorp, arrenderade Träslöv 5:7 av sin farbror Lars Emil Bengtsson. Avtalet ger honom en direkt, dokumenterad brukningskoppling till Valagården under efterkrigstiden.","Arrendet löpte i fem år och omfattade jordbruket samt användning av lada och loge. Om avtalet förlängdes efter 1 april 1963 är ännu okänt.","Familjeberättelsen beskriver hur Axel Harry växte upp på Korsberg, övertog gården 1954 och återvände till Valagården tillsammans med Karin 1985."],"timeline":[["1958-03-25","Arrendekontraktet för Träslöv 5:7 undertecknas av jordägaren Emil Bengtsson."],["1958-04-01–1963-04-01","Brukar Valagårdens fastighet Träslöv 5:7 som arrendator."],["1954","Övertar Korsberg och gifter sig med Karin Johansson enligt familjeberättelsen."],["1985","Överlåter Korsberg till Hans Ingemar och flyttar till Valagården."],["1990","Valagården överlåts enligt familjeberättelsen till dottern Gerd."]],"sources":["IMG_6532.HEIC: originalarrendekontrakt mellan Lars Emil Bengtsson och Harry Bengtsson.","Mormors handskrivna levnadsberättelse och släktblad, mottagna 2026-08-31; sekundära familjekällor."],"uncertainties":["Födelsedagen 18 eller 22 december 1916 och de juridiska formerna för gårdsövergångarna måste verifieras."],"parents":["sven_adolf_bengtsson","gertrud_persdotter"],"children":["ingemar_bengtsson","gerd_bengtsson"]}'::jsonb) where id = 'harry_bengtsson';
