update public.people set content = pg_temp.merge_archive_arrays(content, '{"facts":[["Liv","Flyttade till Klastorp på 1950-talet"],["Avvikelse","Ancestry-skärmbilden visar 1929-2022, men familjeuppgift anger oktober 2023"],["Nästa steg","Komplettera exakt dödsdatum och källa"],["Motstridigt födelsedatum","Tidigare familjeuppgift anger 1929-02-11; ett nytt handskrivet släktblad anger 1929-02-10."],["Ursprung","Skillingshagen i Morup enligt familjeberättelsen."],["Gårdsflytt","Korsberg till Valagården 1985 enligt familjeberättelsen."]],"story":["Karin Margit föds 11 februari 1929 i Morup enligt den senaste morfarsfilen. Hon bär flicknamnet Johansson och tar som gift namnet Bengtsson.","På 1950-talet flyttar hon med Axel Harry Bengtsson till Klastorp. Tillsammans får de barnen Ingemar och Gerd.","Den senaste morfarsfilen anger att familjeuppgiften om död i oktober 2023 ska ges företräde framför Ancestry-trädets 2022-uppgift tills exakt källa kompletteras.","Karin Margit beskrivs i familjematerialet som kommen från Skillingshagen i Morup. Hon bodde med Axel Harry på Korsberg och flyttade med honom till Valagården 1985."],"timeline":[["1929-02-11","Föds i Morup enligt senaste morfarsfilen."],["1950-talet","Flyttar med Harry Bengtsson till Klastorp."],["2023-10","Avlider enligt familjeuppgift; exakt datum ska kompletteras."],["1985","Flyttar med Axel Harry från Korsberg till Valagården enligt familjeberättelsen."]],"sources":["Mormors handskrivna levnadsberättelse och släktblad, mottagna 2026-08-31; sekundära familjekällor."],"uncertainties":["Födelsedagen 10 eller 11 februari 1929 måste avgöras med officiell källa."],"parents":["karl_hjalmar_johansson","ester_viktoria"],"children":["ingemar_bengtsson","gerd_bengtsson"]}'::jsonb) where id = 'karin_margit';
