update public.people set content = pg_temp.merge_archive_arrays(content, '{"aliases":["Gerd Elisabeth Bengtsson"],"facts":[["Make","Göran Nilsson"],["Barn","Axel och Ebba"],["Valagården","Övertog enligt familjeberättelsen Valagården 1990"],["Källstatus gårdsövergång","Privat familjeuppgift; juridisk form och exakt datum behöver verifieras"]],"story":["Gerd föds 6 augusti 1958, dotter till Karin och Harry.","Gerd gifter sig med Göran Nilsson. Tillsammans får de två barn: Axel och Ebba.","Gerd Elisabeth Bengtsson utgör den moderna familjegrenen på Valagården. Enligt familjeberättelsen överläts släktgården till henne 1990."],"timeline":[["1990","Övertar Valagården enligt familjeberättelsen."]],"sources":["Mormors handskrivna släktblad och levnadsberättelse, mottagna 2026-08-31; sekundära familjekällor."],"parents":["karin_margit","harry_bengtsson"],"children":["axel_nilsson","ebba_nilsson"]}'::jsonb) where id = 'gerd_bengtsson';
