update public.people set content = pg_temp.merge_archive_arrays(content, '{"aliases":["Nils Göran Nilsson"],"facts":[["Maka","Gerd Bengtsson"],["Barn","Axel och Ebba"],["Mor","Elsa Helena"],["Far","Nils Stig Henning Nilsson"],["Fullständigare namnform","Nils Göran Nilsson enligt handskrivet familjeblad"]],"story":["Göran Nilsson föds 26 maj 1956. Han är gift med Gerd Bengtsson och tillsammans får de barnen Axel och Ebba.","På pappas sida är hans mor Elsa Helena, född 24 september 1920 i Torpa, och hans far Nils Stig Henning Nilsson, född 13 maj 1924."],"sources":["Mormors handskrivna släktblad, mottaget 2026-08-31; sekundär familjekälla."],"parents":["elsa_helena_karlsson","nils_stig_henning_nilsson"],"children":["axel_nilsson","ebba_nilsson"]}'::jsonb) where id = 'goran_nilsson';
