-- Existing person: sven_adolf_bengtsson
update public.people set content = pg_temp.merge_archive_arrays(content, '{"aliases":["Adolf Bengtsson"],"facts":[["Maka","Gertrud Persdotter"],["Barn","Axel Harry Bengtsson"],["Föräldrar enligt Ancestry-trädet","Bengt A. Nilsson och Sara Britta Andersdotter"],["Källstatus","Preliminär; födelsenotis och familj ska kontrolleras"],["Bror","Lars Emil Bengtsson, som i handlingarna skrev sig Emil Bengtsson."],["Skuldebrev 1928","Fordringsägare till 3 000 kronor från brodern Lars Emil; Sven Adolf anges bo på nr 12 Klastorp."],["Familjekoppling till Valagården","Brodern Lars Emil bodde på Valagården 1955 och ägde Träslöv 5:7 1958."],["Motstridigt födelsedatum","Ancestry anger 1879; äldre familjeblad 1878-03-01 och två nyare familjeblad 1878-03-11."],["Vigsel","1911 med Gertrud Petersson/Persdotter enligt familjeberättelsen"],["Amerikaresa","Reste efter vigseln till Amerika för att tjäna pengar och återvände 1916 enligt familjeberättelsen"],["Korsberg och Hansa","Köpte enligt familjeberättelsen gårdarna efter hemkomsten 1916"],["Barn","Axel Harry, Sven August Robert och Torsten Verner"]],"story":["Sven Adolf Bengtsson förs i senaste morfarsfilen som far till Axel Harry Bengtsson.","Uppgiften kommer från Ancestry-trädet och ska kontrolleras mot födelsenotis, församlingsbok och familjen när Harry föds i Klastorp 1916.","Ett originalskuldebrev daterat 12 november 1928 visar Sven Adolf som fordringsägare när brodern Lars Emil Bengtsson, under namnet Emil Bengtsson, erkände en skuld på 3 000 kronor. Sven Adolf bodde då på nr 12 Klastorp.","Räntan anges i handlingen löpa från 14 mars 1920, åtta år före dateringen. Det kan betyda att 1928 års handling formaliserade ett äldre lån, men detta är ännu en tolkning.","Familjeberättelsen ger en rikare men ännu sekundär bild av Sven Adolf: efter vigseln 1911 reste han till Amerika för att tjäna pengar, återvände 1916 och köpte Hansa och Korsberg i Klastorp.","Familjen bosatte sig på Korsberg. Gertruds affär flyttades dit och gården blev både bostad, jordbruksmiljö och plats för handel."],"timeline":[["1928-11-12","Brodern Lars Emil utfärdar ett skuldebrev på 3 000 kronor till Sven Adolf i Klastorp."],["1911","Gifter sig med Gertrud enligt familjeberättelsen och reser därefter till Amerika."],["1916","Återvänder från Amerika och köper enligt familjeberättelsen Hansa och Korsberg."],["1918-04-24","Sonen Sven August Robert föds enligt familjebladet."],["1920-01-06","Sonen Torsten Verner föds enligt familjebladet."]],"sources":["anteckning om sven adolf.HEIC: originalskuldebrev daterat 1928-11-12.","Mormors handskrivna levnadsberättelse och släktblad, mottagna 2026-08-31; sekundära familjekällor."],"uncertainties":["Födelseåret och dagen, vigseln, Amerikaresans detaljer och gårdsköpen behöver originalbelägg."],"parents":["bengt_a_nilsson","sara_britta_andersdotter"],"children":["harry_bengtsson","sven_august_robert_bengtsson_1918","torsten_verner_bengtsson_1920"]}'::jsonb) where id = 'sven_adolf_bengtsson';
-- Existing person: gertrud_persdotter
update public.people set content = pg_temp.merge_archive_arrays(content, '{"aliases":["Gertrud Petersson"],"facts":[["Make","Sven Adolf Bengtsson"],["Barn","Axel Harry Bengtsson"],["Källstatus","Preliminär från Ancestry-träd"],["Motstridigt namn","Gertrud Persdotter i Ancestry-materialet och Gertrud Petersson i två familjehandlingar"],["Motstridiga födelseuppgifter","Ancestry anger 1875; ett familjeblad anger 1876-11-24"],["Ursprung","Södra Näs enligt familjeberättelsen"],["Syster och handel","Drev speceriaffär i Klastorp tillsammans med systern Anna enligt familjeberättelsen"],["Korsberg","Affärsrörelsen flyttades enligt berättelsen till Korsberg efter Sven Adolfs återkomst"]],"story":["Gertrud Persdotter förs som mor till Axel Harry Bengtsson i senaste morfarsfilen.","Uppgiften är preliminär tills Harrys födelsenotis och familjens församlingsbok har kontrollerats.","Gertrud uppges i familjeberättelsen ha kommit från Södra Näs och ha drivit en speceriaffär i Klastorp tillsammans med sin syster Anna.","Både namnform och födelseuppgift är motstridiga mellan sekundärkällorna. Gertrud Petersson och datumet 1876-11-24 behandlas därför som starka familjespår, inte som avgjorda fakta."],"sources":["Mormors handskrivna levnadsberättelse och släktblad, mottagna 2026-08-31; sekundära familjekällor."],"uncertainties":["Originalnotiser måste avgöra Persdotter/Petersson och födelseår 1875 eller datumet 1876-11-24."],"parents":[],"children":["harry_bengtsson","sven_august_robert_bengtsson_1918","torsten_verner_bengtsson_1920"]}'::jsonb) where id = 'gertrud_persdotter';
-- Existing person: bengt_a_nilsson
update public.people set content = pg_temp.merge_archive_arrays(content, '{"aliases":["Bengt August Nilsson"],"facts":[["Maka","Sara Britta Andersdotter"],["Barn","Nils Johan, Anders G., Karl Oskar, Johan Albin, Alma J., Anna V., Sven Adolf och Lars Emil"],["Föräldrar enligt Ancestry-trädet","Nils Bengtsson och Gunnild Alfredsdotter"],["Anmärkning","Mellannamnet bakom initialen A. är ännu okänt"],["Namnform i Valagården-mastern","Bengt August Nilsson; webbplatsens befintliga namnform Bengt A. Nilsson behålls tills fullständigt namn är slutligt samordnat mellan källorna."],["Delägare 1866","Familjens avskrift om Träslöv 5:6 beskriver Bengt August Nilsson som delägare i gårdens byggnader, sannolikt den kvarboende parten."],["Skuldebrev 1901","Lån på 1 600 kronor till J. O. Reis med sex procents ränta; årliga räntebetalningar kan följas 1902-1911."],["Valagård 1915","Lokalundersökningsblanketten anger Bengt Nilsson d.ä. som ägare/uppgiftslämnare för det 12 hektar stora jordbruket."],["Äganderätt","Handlingarna ger stark gårdskoppling men varje historisk mantalsandel och fastighetsdel måste fortfarande hållas isär."],["Motstridiga födelsedagar","Familjebladen anger 1840-12-01 respektive 1840-12-02; kyrkobokskontroll krävs"],["Dopvittnen","Mormors blad innehåller antecknade faddrar som ska kopplas först efter originalkontroll"]],"story":["Bengt A. Nilsson förs i morfarsfilen som far till Sven Adolf Bengtsson och make till Sara Britta Andersdotter.","Barnaskaran i Ancestry-trädet omfattar åtta kända barn födda mellan 1865 och 1885. Samtliga barns fullständiga datum, födelseorter och koppling till föräldraparet ska kontrolleras.","Valagården-mastern ger Bengt August Nilsson en betydligt tydligare gårdshistoria. Familjens avskrift av förrättningen 1866 beskriver honom som delägare i husen på Träslöv 5:6 och talar sannolikt för att han var den kvarboende parten när Petter Anders Svensson flyttade ut.","Ett skuldebrev från 1901 visar Bengt August under adressen nr 5 Träslöv med en skuld på 1 600 kronor och sex procents ränta. Räntebetalningar är noterade från 1902 till 1911. Säkerheten var indirekt knuten till 3/64 mantal Jöns Nilsgård, men handlingen visar inte ensam att Bengt August ägde just den intecknade andelen.","År 1915 står Bengt Nilsson den äldre som ägare eller uppgiftslämnare för Valagård i lokalundersökningen. Gården omfattade 12 hektar och var nästan helt uppodlad."],"timeline":[["1866-07-04","Familjens avskrift beskriver delning av gårdens byggnader mellan Petter Anders Svensson och Bengt August Nilsson."],["1901-04-04","Utfärdar skuldebrev på 1 600 kronor till J. O. Reis."],["1902-1911","Årliga räntebetalningar antecknas på skuldebrevet."],["1915-08-31","Anges som ägare/uppgiftslämnare för Valagård i lokalundersökningen."]],"sources":["IMG_6524.HEIC och IMG_6525.HEIC: familjeavskrift om byggnadsdelningen 1866.","otydligt.HEIC och otydligt4.HEIC: skuldebrev 1901 och ränteanteckningar 1902-1911.","Lokalundersökningsblankett för Valagård, uppgift lämnad 1915-08-31.","Mormors handskrivna släktanteckningar, mottagna 2026-08-31; sekundär familjekälla."],"uncertainties":["Exakt födelsedag och de antecknade faddrarnas läsning behöver verifieras."],"parents":["nils_bengtsson_1814","gunnild_alfredsdotter"],"children":["nils_johan_bengtsson_1869","anders_g_bengtsson","karl_oskar_bengtsson","johan_albin_bengtsson","alma_j_bengtsdotter","anna_v_bengtsdotter","sven_adolf_bengtsson","lars_emil_bengtsson"]}'::jsonb) where id = 'bengt_a_nilsson';
