update public.people set content = pg_temp.merge_archive_arrays(content, '{"facts":[["Make","Bengt A. Nilsson"],["Källstatus","Preliminär från Ancestry-träd"],["Valagård 1915","Maken Bengt Nilsson d.ä. står i lokalundersökningens ägarfält; blanketten avgör inte om Sara Britta hade juridisk deläganderätt."],["Födelsedatum i familjeblad","1840-07-27; inte originalkontrollerat"]],"story":["Sara Britta Andersdotter förs som maka till Bengt A. Nilsson och mor till Sven Adolf Bengtsson i senaste morfarsfilen.","Uppgifterna är preliminära och behöver kontrolleras i vigselbok, husförhör/församlingsbok och barnens födelsenotiser.","Sara Brittas gårdskoppling till Valagården är etablerad genom hushållet med Bengt August Nilsson. Lokalundersökningen 1915 namnger bara Bengt i ägarfältet, så hennes eventuella juridiska andel lämnas uttryckligen öppen."],"sources":["Mormors handskrivna släktanteckningar, mottagna 2026-08-31; sekundär familjekälla."],"parents":[],"children":["nils_johan_bengtsson_1869","anders_g_bengtsson","karl_oskar_bengtsson","johan_albin_bengtsson","alma_j_bengtsdotter","anna_v_bengtsdotter","sven_adolf_bengtsson","lars_emil_bengtsson"]}'::jsonb) where id = 'sara_britta_andersdotter';
-- Existing person: nils_bengtsson_1814
update public.people set content = pg_temp.merge_archive_arrays(content, '{"facts":[["Döpt","1814-05-12"],["Far","Bengt Olofsson, åbo"],["Mor","Bengta Börgesdotter/Börjesdotter"],["Källa","Träslöv CI:5 (1799-1825), Bild 109 / Sida 211"],["Källstatus","Originalbild och ArkivDigitals födelsepost kontrollerade"],["Avvikelse löst","Rätt datum är 1814-05-11, inte 1814-06-11"],["Död enligt familjeblad","1863-04-24; inte originalkontrollerat"],["Ytterligare barn i familjeblad","Beata Sofia, Carl Johan, Anna Christina, Anders och Beata Lovisa utöver Bengt August"]],"story":["Nils Bengtsson föds 11 maj 1814 och döps dagen därpå i Träslöv.","Födelsenotisen anger föräldrarna åbon Bengt Olofsson och Bengta Börgesdotter samt placerar familjen vid Wahlagården. Detta visar att familjen fanns där redan i maj 1814.","Nils förs som far till Bengt A. Nilsson enligt Ancestry-trädet, men vigseln med Gunnild Alfredsdotter och vidare hushållskopplingar ska fortfarande kontrolleras.","Mormors handskrivna anteckning utökar Nils och Gunnild/Gunnelds barnaskara med fem personer. De förs som sekundärt belagda sidospår och visas inte som bekräftade förrän födelsebok och husförhör har kontrollerats."],"timeline":[["1814-05-11","Föds vid Wahlagården i Träslöv."],["1814-05-12","Döps."],["1840","Sonen Bengt A. Nilsson föds enligt Ancestry-trädet."]],"sources":["Mormors handskrivna släktanteckningar, mottagna 2026-08-31; sekundär familjekälla."],"uncertainties":["Dödsdatumet och hela barnaskaran behöver originalkontrolleras."],"parents":["bengt_olofsson_1784","bengta_borjesdotter_1793"],"children":["bengt_a_nilsson","beata_sofia_1842_nilsdotter_branch","carl_johan_1844_nilsdotter_branch","anna_christina_1846_nilsdotter_branch","anders_1849_nilsdotter_branch","beata_lovisa_1851_nilsdotter_branch"]}'::jsonb) where id = 'nils_bengtsson_1814';
-- Existing person: gunnild_alfredsdotter
update public.people set content = pg_temp.merge_archive_arrays(content, '{"aliases":["Gunneld Arvidsdotter","Gunnel Arvidsdotter","Gunnild Arvidsdotter"],"facts":[["Make","Nils Bengtsson"],["Källstatus","Preliminär; stavning och patronymikon ska kontrolleras mot originalkälla"],["Namnkonflikt","Ancestry anger Gunnild Alfredsdotter; tre familjeblad använder Arvidsdotter med varierande förnamnsstavning"],["Datumkonflikt","Familjeblad anger 1809-07-17 respektive 1809-04-17; april förekommer i två blad"],["Barn i familjeblad","Bengt August, Beata Sofia, Carl Johan, Anna Christina, Anders och Beata Lovisa"]],"story":["Gunnild Alfredsdotter förs i senaste morfarsfilen som maka till Nils Bengtsson och mor till Bengt A. Nilsson.","Stavningen återges från Ancestry-trädet och behöver kontrolleras mot originalkällor.","Mormors familjeblad ger en tydlig men ännu olöst konflikt kring Gunnilds namn. Arvidsdotter återkommer i flera blad, medan Ancestry uppger Alfredsdotter.","Även födelsemånaden varierar. Apriluppgiften har stöd i två familjeblad och juli i ett, men ingen får låsas innan originalnotis, vigsel och husförhör har kontrollerats."],"sources":["Mormors handskrivna släktanteckningar, mottagna 2026-08-31; sekundära familjekällor."],"uncertainties":["Huvudnamn, patronymikon och födelsedatum är olösta sekundärkällkonflikter."],"parents":[],"children":["bengt_a_nilsson","beata_sofia_1842_nilsdotter_branch","carl_johan_1844_nilsdotter_branch","anna_christina_1846_nilsdotter_branch","anders_1849_nilsdotter_branch","beata_lovisa_1851_nilsdotter_branch"]}'::jsonb) where id = 'gunnild_alfredsdotter';
-- Existing person: nils_martensson_1740
update public.people set content = pg_temp.merge_archive_arrays(content, '{"facts":[["Ålder i bouppteckning 1762","ca 22 år"],["Sekundär uppgift","Leif Lundquist anger född 1740-08-08 vid Valagård"],["Källstatus","Bouppteckning + sekundär uppgift"],["Född","1740-08-08"],["Döpt","1740-08-10 i Träslövs kyrka"],["Gårdsfras","Kan med hög sannolikhet läsas ''af Jöns Nilsgården''"],["Faddrar","Lars Andersson, Hans Mårtensson i Träslöv, Börje Andersson, Elisabet Börgesdotter och pigan Anna Olofsdotter; flera gårds- och namnformer är preliminära"]],"story":["Nils räknas upp som barn i bouppteckningen efter Mårten Andersson. Leif Lundquists antavla anger födelsedatumet 1740-08-08 vid Valagård, vilket bör kontrolleras i original.","Den återfunna originalnotisen bekräftar Nils födelse och dop samt föräldrarna Mårten Andersson och Helena Jönsdotter. Gårdsfrasen Jöns Nilsgården är stark men något mindre säker än personnamnen och datumen.","Fyndet flyttar familjens tidigaste nuvarande originalspår vid Jöns/Jon Nilsgård tillbaka till 1740. Det visar gårdsanknytning men inte köp, arv, ägande eller åborätt."],"timeline":[["1740-08-08","Föds med stark gårdsanknytning till Jöns Nilsgården."],["1740-08-10","Döps i Träslövs kyrka."]],"sources":["Träslövs födelse- och dopbok 1740, originalnotis återgiven i morfars master v125; full arkivsignatur återstår."],"uncertainties":["Gårdsordet och flera faddrars patronymikon eller hemvist behöver kontrolleras i bästa originalbild."],"parents":["marten_andersson_1701","helena_jonsdotter_1713"],"children":[]}'::jsonb) where id = 'nils_martensson_1740';
-- Existing person: marten_andersson_1701
update public.people set content = pg_temp.merge_archive_arrays(content, '{"facts":[["Begravd","1762-08-01"],["Dödsorsak","Bröstfeber"],["Bouppteckning","1762-10-21, Himle häradsrätt FIIb:3, Sida 9"],["Make","Helena Jönsdotter"],["Barn","Anna, Börta, Kerstin, Nils, Karin, Jöns, Anders och Börje"],["Källstatus","Dödsnotis och bouppteckning placerar honom vid Jöns Nilsgård"],["Vigselnotis 1731","Mårten anges som dräng i Träslöfs by; notisen innehåller inget säkert Valagårdsbelägg."],["Husförhör ca 1756-1759","Mårtens familj står under gårdsrubriken Jon Nilsgård tillsammans med ett separat hushåll för Börge Andersson."],["Korrigerad läsning","Den femåriga personen i N:o 42-materialet omkring 1700 är Kirsti/Kerstin Andersdotter, inte Mårten Andersson."],["Tidigaste starka gårdsspår","Sonen Nils födelsenotis 1740 placerar familjen med hög sannolikhet vid Jöns Nilsgården"]],"story":["Mårten Andersson dör 27 juli 1762 vid Jöns Nilsgård i Träslöv och begravs 1 augusti. Åldern pekar mot födelse omkring 1701.","Bouppteckningen efter Mårten förrättades 21 oktober 1762 och nämner änkan Helena Jönsdotter samt åtta barn. Dottern Anna, cirka 30 år, binder honom till Anna Mårtensdotter född 1732.","Hans födelseort och föräldrar är ännu inte originalbekräftade. Nygård-spåret och en möjlig Mårten Andersson i tidiga gårdslistor ska fortsatt prövas källkritiskt.","Valagården-mastern avgränsar den säkra gårdskopplingen noggrant: vigseln 1731 visar bara Mårten som dräng i Träslöfs by. Husförhöret omkring 1756-1759 och originalhandlingarna från 1762 ger däremot starka belägg för familjen vid Jon/Jöns Nilsgård."],"timeline":[["1731-04-25","Vigs med Helena Jönsdotter."],["1732-04-24","Dottern Anna Mårtensdotter föds."],["1762-07-27","Dör vid Jöns Nilsgård av bröstfeber."],["1762-08-01","Begravs."],["1762-10-21","Bouppteckning förrättas efter honom."],["1740-08-08","Sonen Nils föds med starkt läst anknytning till Jöns Nilsgården."]],"sources":["Träslöv (N) CI:4, Bild 1410 / Sida 267; Himle häradsrätt FIIb:3, originalsid 9.","Träslövs födelse- och dopbok 1740, originalnotis i morfars master v125."],"parents":[],"children":["anna_martensdotter_jon_nilsgard","borta_martensdotter","kerstin_martensdotter","nils_martensson_1740","karin_martensdotter","jons_martensson","anders_martensson","borje_martensson"]}'::jsonb) where id = 'marten_andersson_1701';
-- Existing person: helena_jonsdotter_1713
update public.people set content = pg_temp.merge_archive_arrays(content, '{"facts":[["Född","mellan 6 och 7 oktober 1713"],["Döpt","1713-10-08"],["Far","Jöns/Jonas Andersson Polin, klockaren"],["Mor","Kari/Karin Helgesdotter"],["Faddrar","Bland annat Jöns Grimberg, Mathias Höök, Olof Börgesson i Lunden, Anders Gillberg/Cillberg, Elisabet Bruhn och personer från Varberg; möjlig Agneta Bolin/Polin ska kontrolleras"],["Vigsel","1731-04-25 med Mårten Andersson"],["Hemvist vid vigsel","Skultagården"],["Bouppteckning","1800-10-13 vid N:o 5 Jon Nilsgård"],["Källstatus","Födelse/dop, vigsel och bouppteckning är starkt belagda; fadderläsningarna är delvis preliminära"],["Valagårdskoppling","Vigseln 1731 anger Skultagården, inte Valagården. Bouppteckningen 1800 placerar henne däremot vid N:o 5 Jon Nilsgård."],["Åldersskillnad i Valagården-mastern","Personöversikten återger den äldre sekundära uppskattningen omkring 1709, medan den befintliga originaltolkningen anger födelse 1713-10-06/07. Båda uppgifterna bevaras med olika källstatus."],["Husförhör 1773–1788","Står som änkan Helena Jönsdotter under Jon Nils gård; längden anger det avvikande födelseåret 1712"],["Tre generationer på gårdssidan","Helena, dottern Anna Mårtensdotter och dotterdottern Anna Olofsdotter finns under samma gårdsrubrik"]],"story":["Helena Jönsdotter föds under natten mellan 6 och 7 oktober 1713 och döps 8 oktober i Träslöv. Födelsenotisen anger henne som klockarens dotter, vilket i sammanhanget binder henne till Jöns/Jonas Andersson Polin och Karin Helgesdotter.","Fadderkretsen är ovanligt intressant: den innehåller ämbetsmannamässiga namn, personer från Varberg och Lunden samt en möjlig Polin/Bolin-person. Det passar väl med Jöns Polins roll som klockare och hans Varbergskoppling.","Vid vigseln med Mårten Andersson 1731 anges Helena som piga från Skultagården. Det visar hemvist vid vigseln, men inte säkert födelsegård.","Bouppteckningen efter Helena 1800 placerar henne vid N:o 5 Jon Nilsgård och nämner dottern Anna, gift med Olof Andersson. Det ger ytterligare stöd för Valagård/Jon Nilsgård-kedjan.","Valagården-masterns personöversikt återger en äldre ungefärlig födelsetid omkring 1709. Webbplatsens redan publicerade uppgift 1713 bygger på den starkare födelse- och dopnotisen och behålls; avvikelsen dokumenteras i stället för att jämnas ut.","Ett husförhör 1773–1788 samlar tre generationer av den direkta kvinnolinjen under Jon Nils gård. Helena står som änka, medan dottern Anna Mårtensdotter och dotterdottern Anna Olofsdotter finns i Olof Anderssons hushåll."],"timeline":[["1713-10-06/07","Föds under natten mellan 6 och 7 oktober."],["1713-10-08","Döps i Träslöv."],["1731-04-25","Vigs med Mårten Andersson och anges som piga från Skultagården."],["1800-05-29","Dör sannolikt enligt bouppteckningen."],["1800-10-13","Bouppteckning förrättas vid N:o 5 Jon Nilsgård."],["1773–1788","Står som änka under Jon Nils gård tillsammans med den större gårdsmiljö där dottern och dotterdottern återfinns."]],"sources":["Himle häradsrätt FIIa:11 (1800-1802), bouppteckning efter Helena Jönsdotter.","Riksarkivets husförhörslängd 1773–1788, Jon Nils gård; exakt volym, bild och sida återstår."],"uncertainties":["Längdens födelseår 1712 ersätter inte originalnotisen från 1713."],"parents":["jons_polin_1682","karin_helgesdotter_1685"],"children":["anna_martensdotter_jon_nilsgard","borta_martensdotter","kerstin_martensdotter","nils_martensson_1740","karin_martensdotter","jons_martensson","anders_martensson","borje_martensson"]}'::jsonb) where id = 'helena_jonsdotter_1713';
-- Existing person: anna_martensdotter_jon_nilsgard
update public.people set content = pg_temp.merge_archive_arrays(content, '{"facts":[["Döpt","1732-04-28"],["Far","Mårten Andersson"],["Mor","Helena Jönsdotter"],["Vigsel","1765-02-10 med Olof Andersson från Dagsås"],["Ålder i Mårtens bouppteckning 1762","ca 30 år"],["Källstatus","Födelsenotis, vigselnotis och bouppteckning bekräftar identiteten"],["Gårdsövergång","Piga från Jön Nilsgård vid vigseln 1765; maken Olof Andersson kom från Dagsås."],["Källvärde","Mårtens bouppteckning 1762 nämner en dotter Anna, 30 år, vilket passar födelsen 1732."],["Husförhör 1773–1788","Står med maken Olof Andersson och dottern Anna under Jon Nils gård"]],"story":["Anna Mårtensdotter föds 24 april 1732 och döps 28 april. Födelsenotisen anger föräldrarna Mårten Andersson och Helena Jönsdotter.","Mårten Anderssons bouppteckning 1762 nämner dottern Anna, cirka 30 år, vilket stämmer med födelsenotisen 1732. Vid vigseln 1765 anges Anna som piga från Träslöv Jön Nilsgård.","Genom Anna går den källbelagda gårdskedjan vidare från Mårten och Helena till dottern Anna Olofsdotter och senare Bengta Börjesdotter."],"timeline":[["1732-04-24","Föds i Träslöv."],["1732-04-28","Döps."],["1762-10-21","Nämns som dotter, ca 30 år, i Mårten Anderssons bouppteckning."],["1765-02-10","Vigs med Olof Andersson från Dagsås."],["1767-06-17","Dottern Anna Olofsdotter föds vid Jon Nilsgård."],["1773–1788","Återfinns med make och dotter under Jon Nils gård."]],"sources":["Träslöv födelse- och dopbok 1732, originalsid 65; Träslöv (N) CI:4, Bild 1180 / Sida 223.","Riksarkivets husförhörslängd 1773–1788, Jon Nils gård; exakt volym, bild och sida återstår."],"parents":["marten_andersson_1701","helena_jonsdotter_1713"],"children":["anna_olofsdotter_1767"]}'::jsonb) where id = 'anna_martensdotter_jon_nilsgard';
-- Existing person: anna_olofsdotter_1767
update public.people set content = pg_temp.merge_archive_arrays(content, '{"facts":[["Döpt","1767-06-21"],["Far","Olof Andersson"],["Mor","Anna Mårtensdotter"],["Vigsel","1790-12-26 med Börje Pehrsson"],["Hemort vid vigsel","Träslöf Valagård"],["Bostad som vuxen","N:o 5 Jon Nilsgård"],["Ålder vid Bengtas födelse","26 år"],["Källa","Träslöv CI:4 (1747-1798), Bild 490 / Sida 87"],["Husförhör 1773–1788","Står som dottern Anna, född 1767, i Olof Anderssons och Anna Mårtensdotters hushåll på Jon Nils gård"]],"story":["Anna Olofsdotter föds 17 juni 1767 vid Jon Nilsgård i Träslöv och döps 21 juni. Originalnotisen anger föräldrarna Olof Andersson och Anna Mårtensdotter.","Vid vigseln 1790 anges Anna som piga från Träslöf Valagård, medan Börje Pehrsson kommer från Klastorps Buragård. Det visar att gårdskopplingen i denna generation går genom Anna.","Husförhöret vid N:o 5 Jon Nilsgård placerar Anna och Börje i samma gårdsmiljö som Annas föräldrar, vilket gör gårdskedjan genom Bengta Börjesdotters mödernelinje mycket stark."],"timeline":[["1767-06-17","Föds vid Jon Nilsgård, Träslöv."],["1767-06-21","Döps."],["1790-12-26","Vigs med Börje Pehrsson."],["1793-10-25","Dottern Bengta föds."],["1773–1788","Återfinns som barn i föräldrahushållet på Jon Nils gård."]],"sources":["Riksarkivets husförhörslängd 1773–1788, Jon Nils gård; exakt volym, bild och sida återstår."],"parents":["olof_andersson_jon_nilsgard","anna_martensdotter_jon_nilsgard"],"children":["bengta_borjesdotter_1793"]}'::jsonb) where id = 'anna_olofsdotter_1767';
-- Existing person: anders_jonsson_polin
update public.people set content = pg_temp.merge_archive_arrays(content, '{"facts":[["Yrke","Sadelmakare"],["Hustru","Ingrid"],["Son","Jöns/Jonas Andersson Polin"],["Källstatus","Leif Lundquist"],["Sekundära levnadsår","Född 1645 och död 1706 enligt ortnamnsregister till 50 halländska antavlor"],["Originalkandidat 1706","En Anders Jönsson begravdes 1706-06-06 på gamla kyrkogården i Varberg, 65 år gammal; Polin-namn och yrke saknas i notisen"],["Möjlig far","Jöns Andersson, kallad Jöns i Pölen, enligt sekundära antavlor"]],"story":["Anders Jönsson Polin förs in som far till Jöns/Jonas Andersson Polin enligt Leif Lundquists Halländsk antavla 4. Uppgiften är en accepterad arbetsgenealogi och ska originalkontrolleras när källor hittas.","En originalpost i Varbergs dödbok 1706 är den starkaste kandidaten hittills till Anders begravning. Namn, ort och år passar, men eftersom notisen saknar både Polin och yrket sadelmakare betraktas identiteten som sannolik men obekräftad."],"timeline":[["1706-06-06","En möjlig Anders Jönsson begravs på gamla kyrkogården i Varberg, 65 år gammal; identiteten är inte slutligt bevisad."]],"sources":["Varbergs död- och begravningsbok 1706, sida 88; kandidatpost.","Leif Lundquist, Halländsk antavla 4; sekundär forskning.","Ortnamnsregistret till 50 halländska antavlor; sekundär forskning."],"uncertainties":["Kandidatposten 1706 saknar Polin-namn och yrkestitel och kan därför inte låsas som Anders Jönsson Polin."],"parents":["jons_andersson_polen"],"children":["jons_polin_1682"]}'::jsonb) where id = 'anders_jonsson_polin';
-- Existing person: ingrid_polin
update public.people set content = pg_temp.merge_archive_arrays(content, '{"aliases":["Inger Andersdotter"],"facts":[["Make","Anders Jönsson Polin"],["Son","Jöns/Jonas Andersson Polin"],["Källstatus","Leif Lundquist"],["Notering","Patronymikonet Andersdotter ska inte låsas utan ytterligare källa"],["Namnstatus","Ingrid hos Leif Lundquist; Inger Andersdotter i ortnamnsregister och Ancestry, samtliga sekundära källor"],["Gårdsavgränsning","Sonen Jöns knyts till Lars Trulsgård/Klockaregården, men Ingrid är inte själv belagd som boende eller död där"]],"story":["Ingrid förs in som mor till Jöns/Jonas Andersson Polin enligt Leif Lundquist. Ett Ancestry-träd anger Inger Andersdotter, men patronymikonet lämnas öppet tills en bättre källa finns."],"sources":["Leif Lundquist, Halländsk antavla 4.","Ortnamnsregistret till 50 halländska antavlor; sekundär källa."],"uncertainties":["Namnformen Inger Andersdotter är stärkt av två sekundära källor men inte originalbelagd."],"parents":[],"children":["jons_polin_1682"]}'::jsonb) where id = 'ingrid_polin';
-- Existing person: jons_polin_1682
update public.people set content = pg_temp.merge_archive_arrays(content, '{"facts":[["Yrke","Klockare"],["Begravd","1758-06-04"],["Dödsorsak","Ålderdomskrämpor"],["Gravplats","Troligen vid Träslövs kyrkas västra kyrkogavel, nära stora porten och på norra sidan. Läsningen är medel-hög som gravplatsbeskrivning men medel för exakt ordalydelse."],["Klockaretjänst","Kom till tjänsten 1703; lämnade efter 1747 till mågen Bengt Ehn"],["Vigsel","1705-03-19 med Kari/Karin Helgesdotter"],["Skultagårdsspår","Sannolikt fadder/vittne vid Skultagården 1704-07-10, året före vigseln"],["Kyrkoboksspår","Signaturen J. A. Polin vid slutet av 1707 års kyrkoboksanteckningar är ett mycket starkt indicium på hans skrivande/kyrkliga roll"],["Barnspår","Beata 1707, Helena 1713, Petter 1721, Kerstin/Kirsti 1725 och Anna 1728 förs som starka eller sannolika Polin-barn med olika källstatus"],["Polin-nätverk","Lars Polin förekommer sannolikt som fadder 1707 och har ett separat vigselindex i Varberg med Maria Jöransdotter; relationen till Jöns är ännu okänd"],["Far","Anders Jönsson Polin enligt Leif Lundquist"],["Mor","Ingrid enligt Leif Lundquist"],["Källstatus","Vigsel, Helenas födelsenotis och Jöns dödsnotis originalkontrollerade; fadder- och syskonspår från v102 är delvis starka men ska fortsatt omläsas"],["Gård 1729","Ett lokalt gårdsblad återger Jöns Paulin som åbo på 1/4 mantal krono Lars Trulsgård/Klockaregården med hustru, två döttrar och en dräng"],["Namnhypotes","Polin kan möjligen ha samband med Pölen/Jöns i Pölen, men detta är en uttrycklig hypotes och inte källbelagt"],["Klockaregårdens efterföljare","Mågen Bengt Ehn och dottern Anna Polin återfinns på N:o 1 Klockaregården 1773–1788"]],"story":["Jöns eller Jonas Andersson Polin var klockare i Träslöv och kom enligt dödsnotisen till klockaretjänsten 1703. Dödsnotisen anger att han kom från Varberg, levde måttfullt och gudfruktigt samt lämnade tjänsten efter 1747 till sin måg Bengt Ehn.","V102-materialet gör honom mer levande: han förekommer sannolikt som fadder vid Skultagården redan 1704, året före vigseln med Karin Helgesdotter. Det bevisar inte hemvist där, men visar troligen ett tidigt socialt band till Karins familjemiljö.","I kyrkoboken för 1707 finns en stark signatur/årsslutsnotering som läses J. A. Polin. Den passar Jöns Andersson Polin och antyder att han själv kan ha varit inblandad i förandet eller sammanställningen av kyrkoboken.","Specialavsnittet för Klockaregården/Prästgården ger starka Polin-familjehändelser: Beata 1707, Helena 1713 och Petter 1721. Senare poster för Kerstin/Kirsti 1725 och Anna 1728 hör också till familjens sidospår.","Slutraderna i dödsnotisen bedöms sannolikt beskriva gravplatsen: vid västra kyrkogaveln, nära stora porten, på norra sidan. Uppgiften är viktig för lokalhistorien men ska hållas försiktigt tills ordalydelsen är helt säker.","Det lokala gårdsbladet placerar Jöns Paulin som åbo på Lars Trulsgård/Klockaregården 1729. Avskriften beskriver ett hushåll med hustru, två döttrar och en dräng samt gårdens byggnader och odling.","En möjlig språklig koppling mellan Polin och tillnamnet Jöns i Pölen har väckts i forskningen. Den ska endast visas som hypotes tills originalmaterial visar hur och när släktnamnet började användas."],"timeline":[["ca 1682","Föds eller kommer från Varberg enligt dödsnotisen."],["1703","Kommer till klockaretjänsten i Träslöv."],["1704-07-10","Förekommer sannolikt som fadder/vittne i Skultagårdens material."],["1705-03-19","Vigs med Kari/Karin Helgesdotter."],["1707-04-15/17","Dottern Beata föds/döps enligt mycket stark Polin-post i Klockaregården/Prästgården-avsnittet."],["1707","J. A. Polin-signaturen avslutar sannolikt årets kyrkoboksanteckningar."],["1713-10-06/07","Dottern Helena föds."],["1721-10-31/11-05","Sonen Petter föds och döps enligt stark Polin-post."],["1725-08-12/15","Dottern Kerstin/Kirsti föds och döps enligt sannolik Polin-post; möjlig Mårten Andersson som fadder är obekräftad."],["1728-01-21/26","Dottern Anna föds och döps enligt Polin-familjepost."],["efter 1747","Lämnar klockaretjänsten till mågen Bengt Ehn."],["1758-05-24","Dör av ålderdomskrämpor."],["1758-06-04","Begravs. Gravplatsen tolkas sannolikt som vid västra kyrkogaveln, nära stora porten, på norra sidan."],["1729","Placeras som åbo på Lars Trulsgård/Klockaregården i ett sekundärt gårdsblad som återger landsbeskrivningen."],["1773–1788","Dottern Anna Polin och mågen Bengt Ehn återfinns på N:o 1 Klockaregården."]],"sources":["historia klockaregård.HEIC, lokalt maskinskrivet gårdsblad; sekundär källa.","Riksarkivets husförhör 1773–1788, N:o 1 Klockaregården; full referens återstår."],"uncertainties":["1729 års landsbeskrivning behöver kontrolleras i original och de två onamngivna döttrarna får inte identifieras säkert."],"parents":["anders_jonsson_polin","ingrid_polin"],"children":["beata_jonsdotter_polin","helena_jonsdotter_1713","petter_jonsson_polin","kerstin_jonsdotter_polin_1725","anna_jonsdotter_polin_1728"]}'::jsonb) where id = 'jons_polin_1682';
-- Existing person: anna_jonsdotter_polin_1728
update public.people set content = pg_temp.merge_archive_arrays(content, '{"aliases":["Anna Polin","Anna Jönsdotter Polin"],"facts":[["Döpt","1728-01-26"],["Far","Sannolikt Jöns/Jonas Andersson Polin"],["Källstatus","Polin-familjepost i v102; fadderlistan är ännu inte fullständigt normaliserad"],["Make","Klockaren Bengt Ehn"],["Husförhör 1773–1788","Står som hustru Anna Polin på N:o 1 Klockaregården"],["Dödsnotering i husförhör","Mycket stark läsning: död 1779-03-06; separat dödbokskontroll återstår"],["Barn i matrikel","Eric, Jöns, Anders och Hans Ehn; kyrkoböcker bör kontrolleras"]],"story":["Anna är ett sidospår i Polin-familjen och visar att familjen fortfarande är aktiv i den kyrkliga/klockareanknutna miljön i slutet av 1720-talet.","Fadderlistan är lång men ännu för osäker för att normaliseras fullt ut i trädet.","Anna Jönsdotter Polin förde Klockaregårdens ämbetsmiljö vidare genom äktenskapet med Bengt Ehn, som efterträdde hennes far Jöns Polin som klockare.","Husförhöret 1773–1788 placerar paret på N:o 1 Klockaregården. En marginalnotering anger mycket sannolikt Annas död den 6 mars 1779, men datumet ska kontrolleras i dödboken."],"timeline":[["1728-01-21","Föds enligt Polin-familjepost."],["1728-01-26","Döps."],["1773–1788","Återfinns som hustru till klockaren Bengt Ehn på N:o 1 Klockaregården."],["1779-03-06","Mycket stark dödsnotering i husförhör; separat dödbokskontroll återstår."]],"sources":["Riksarkivets husförhörslängd 1773–1788, N:o 1 Klockaregården; exakt volym, bild och sida återstår.","Carl Sjöström, Göteborgs nation i Lund 1669–1906 (1907), s. 198."],"uncertainties":["Dödsdatumet behöver bekräftas i separat död- eller begravningsnotis."],"parents":["jons_polin_1682","karin_helgesdotter_1685"],"children":["eric_ehn_1748","jons_ehn_1750","anders_ehn_1757","hans_ehn"]}'::jsonb) where id = 'anna_jonsdotter_polin_1728';
-- Existing person: helge_svensson
update public.people set content = pg_temp.merge_archive_arrays(content, '{"facts":[["Hustru","Kerstin Olsdotter"],["Barn i hushåll","Olof, Simon, Inger, sannolikt Margareta, Anders och Karin Helgesdotter enligt N:o 26-hushållet"],["Hushållsfynd","På N:o 26 Niels Olufs Hemman läses Helge Svensson omkring 40 år med hustru och barn; detta är ett mycket viktigt originalspår"],["Begravd","1731-04-16 enligt v102-materialets samlade bedömning"],["Ålder vid begravning","omkring 80 år"],["Äldre uppgift","1731-04-02 från Leif Lundquist ska inte längre användas som exakt originalbekräftat dödsdatum utan kontroll"],["Källstatus","Föräldrakopplingen bygger på Leif Lundquist och stärks kraftigt av hushållet på Nils Olsgård; begravningsuppgiften behöver hållas källkritiskt"],["Originalbekräftad begravning","Begravd 1731-04-16 och uttryckligen kallad mannen ''af Skultagården'', 80 år gammal"],["Gravplats","Notisen anger att han ligger i gårdens gravställe"],["Dödsdatum enligt sekundär forskning","1731-04-02 hos Leif Lundquist; dagen står inte i begravningsnotisen"]],"story":["Helge Svensson förs in som far till Karin Helgesdotter enligt Leif Lundquist, men v102 ger ett mycket starkare gårds- och hushållsspår. På N:o 26 Niels Olufs Hemman i Träslöv finns ett hushåll som med hög sannolikhet innehåller Helge, hustrun Kerstin Olsdotter och flera barn, däribland Karin.","Åldersuppgifterna passar den övriga källbilden: Helge anges omkring 40 år i hushållet och omkring 80 år vid begravningen 1731, vilket pekar mot födelse omkring 1650-1651.","Arbetsbilden är nu att Helge och familjen först hör till Nils Olsgård/Niels Olufs Hemman, medan kopplingen till Skultagården blir tydligare senare. Det viktiga framåt är att hitta exakt när och varför familjen flyttar eller knyts dit.","En tydligare originalbild har rättat det äldre arbetsläget: Helge Svensson finns i begravningsboken den 16 april 1731 och anges uttryckligen vara från Skultagården. Därmed är hans anknytning till gården originalbelagd.","Notisen säger att han ligger i gårdens gravställe. Det separata dödsdatumet 2 april kommer fortsatt från sekundär forskning och ska inte blandas ihop med det bekräftade begravningsdatumet."],"timeline":[["ca 1650","Föds ungefärligen utifrån åldersuppgifter."],["ca 1690","Återfinns sannolikt med hustru och barn på N:o 26 Niels Olufs Hemman / Nils Olsgård."],["1705","Dottern Karin gifter sig med Jöns/Jonas Andersson Polin."],["1731-04-16","Begravs enligt v102-materialets samlade bedömning; äldre datum 1731-04-02 hålls som sekundärt/ej exakt säkrat."],["1731-04-16","Begravs som mannen från Skultagården, 80 år gammal; notisen anger gårdens gravställe."]],"sources":["Träslövs död- och begravningsbok 1731, originalsid 225; originalbild kontrollerad i v125."],"uncertainties":["Dödsdatumet 1731-04-02 är sekundärt och återstår att belägga separat."],"parents":[],"children":["karin_helgesdotter_1685"]}'::jsonb) where id = 'helge_svensson';

