insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,publish_status,content) values('sven_august_robert_bengtsson_1918','sven-august-robert-bengtsson','Sven August Robert Bengtsson','Robert Bengtsson','mother',false,true,'family','published','{"name":"Sven August Robert Bengtsson","aliases":["Robert Bengtsson"],"born":"1918-04-24","role":"Syskon till Axel Harry","status":"working","branch":"mother","place":"Korsberg, Klastorp / Falkenberg","facts":[["Maka","Namnformen ser ut som Viarna Olsson och måste kontrolleras"],["Vigsel","1957 enligt familjeberättelsen"],["Försörjning","Uppges ha varit delägare i ett Falkenbergsföretag vars namn möjligen läses Wulken"],["Källstatus","Handskriven familjeberättelse; namn och företagsuppgift är osäkra"]],"story":["Sven August Robert Bengtsson föds 24 april 1918 som son till Sven Adolf Bengtsson och Gertrud Petersson/Persdotter enligt familjeberättelsen.","Han uppges ha gift sig 1957 med en kvinna från Sjönevad i Vessige. Hennes namn ser ut som Viarna Olsson, men den ovanliga läsningen ska inte låsas före kontroll."],"timeline":[["1918-04-24","Föds enligt handskrivet familjematerial."],["1957","Gifter sig enligt familjeberättelsen; makans namn är osäkert."]],"parents":["sven_adolf_bengtsson","gertrud_persdotter"],"children":[],"sources":["Mormors handskrivna levnadsberättelse, mottagen 2026-08-31; sekundär familjekälla."],"uncertainties":["Makans namn och företagsnamnet i Falkenberg är svårlästa och får inte behandlas som säkra."],"partner":"viarna_olsson_sjonevad"}'::jsonb) on conflict(id) do update set content=pg_temp.merge_archive_arrays(public.people.content,excluded.content),alt_name=coalesce(public.people.alt_name,excluded.alt_name),updated_at=now();
