insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,publish_status,content) values('torsten_verner_bengtsson_1920','torsten-verner-bengtsson','Torsten Verner Bengtsson',null,'mother',false,true,'family','published','{"name":"Torsten Verner Bengtsson","born":"1920-01-06","role":"Syskon till Axel Harry","status":"working","branch":"mother","place":"Hansa, Klastorp","facts":[["Maka","Anna-Lisa Karlsson"],["Vigsel","1955 enligt familjeberättelsen"],["Verksamhet","Byggde 1954 en bilverkstad med bostad på Hansa"],["Källstatus","Handskriven familjeberättelse; inte originalkontrollerat"]],"story":["Torsten Verner Bengtsson föds 6 januari 1920 som son till Sven Adolf Bengtsson och Gertrud Petersson/Persdotter enligt familjematerialet.","År 1954 uppges han ha byggt en bilverkstad med bostad på Hansa. Han gifte sig 1955 med Anna-Lisa Karlsson från Länna församling i Roslagen."],"timeline":[["1920-01-06","Föds enligt handskrivet familjematerial."],["1954","Bygger enligt familjeberättelsen bilverkstad och bostad på Hansa."],["1955","Gifter sig med Anna-Lisa Karlsson enligt familjeberättelsen."]],"parents":["sven_adolf_bengtsson","gertrud_persdotter"],"children":[],"sources":["Mormors handskrivna levnadsberättelse, mottagen 2026-08-31; sekundär familjekälla."],"partner":"anna_lisa_karlsson_lanna"}'::jsonb) on conflict(id) do update set content=pg_temp.merge_archive_arrays(public.people.content,excluded.content),alt_name=coalesce(public.people.alt_name,excluded.alt_name),updated_at=now();
