insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,publish_status,content) values('jons_andersson_polen','jons-andersson','Jöns Andersson','Jöns i Pölen','mother',false,false,'public','published','{"name":"Jöns Andersson","aliases":["Jöns i Pölen"],"role":"Möjlig far till Anders Jönsson Polin","status":"working","branch":"mother","place":"Pölen, Gödestad / Varberg","facts":[["Ställning","Borgare i Varberg enligt sekundär forskning"],["Dödsår","1675 i en antavla och 1676 i ett publikt webtrees-träd"],["Släktuppgift","Anges som far till Anders Jönsson Polin och stamfar till klockaresläkten Polin"],["Källstatus","Sekundär forskning; originalbelägg saknas"]],"story":["Jöns Andersson, kallad Jöns i Pölen, förs som ett nytt men ännu obekräftat generationsspår före Anders Jönsson Polin.","Halländsk antavla 4 och en antavla sammanställd av Ivar Larsson binder honom till Pölen i Gödestad och Varbergs borgarmiljö. Uppgifterna är forskningsledning och inte ett originalbevis."],"timeline":[["1675/1676","Motstridigt dödsår i två sekundära sammanställningar."]],"parents":[],"children":["anders_jonsson_polin"],"sources":["Leif Lundquist, Halländsk antavla 4.","Ivar Larssons antavla i Ingemund Bengtsson II – Varbergs berömde son.","Hallqvist–Winroth, publikt webtrees-träd; sekundär källa."],"uncertainties":["Far–son-kopplingen till Anders Jönsson Polin, dödsåret och uppgiften om Pölen måste verifieras i originalmaterial."]}'::jsonb) on conflict(id) do update set content=pg_temp.merge_archive_arrays(public.people.content,excluded.content),alt_name=coalesce(public.people.alt_name,excluded.alt_name),updated_at=now();
