insert into public.people(id,slug,name,alt_name,branch,is_direct,is_living,visibility,publish_status,content) values('bengt_ehn_1726','bengt-ehn','Bengt Ehn',null,'mother',false,false,'public','published','{"name":"Bengt Ehn","born":"1726","died":"1792","role":"Klockare och måg till Jöns Polin","status":"likely","branch":"mother","place":"Klockaregården, Träslöv","facts":[["Yrke","Klockare"],["Första maka","Anna Jönsdotter Polin"],["Senare maka","Anna/Anne Maja Lomberg"],["Klockaretjänst","Tog över tjänsten efter svärfadern Jöns Polin"],["Källstatus","Husförhör 1773–1788 och tryckt matrikel ger starkt stöd; full arkivreferens till husförhöret återstår"]],"story":["Bengt Ehn tog över klockaretjänsten efter sin svärfar Jöns Polin och återfinns med titeln klockare på N:o 1 Klockaregården i husförhörslängden 1773–1788.","Äktenskapet med Anna Jönsdotter Polin visar hur tjänsten och gårdsmiljön fördes vidare genom en sidogren. Senare återfinns också Anna/Anne Maja Lomberg i hushållet."],"parents":[],"children":["eric_ehn_1748","jons_ehn_1750","anders_ehn_1757","hans_ehn","johannes_ehn_1771"],"sources":["Riksarkivets husförhörslängd 1773–1788, N:o 1 Klockaregården; exakt volym, bild och sida återstår.","Carl Sjöström, Göteborgs nation i Lund 1669–1906 (1907), s. 198.","Jöns Polins dödsnotis 1758."],"uncertainties":["Gårdsbladets tjänsteår 1756–1789 är en sekundär sammanställning och har frågetecken; originalnotisen säger att övertagandet skedde efter 1747."],"partner":"anna_jonsdotter_polin_1728"}'::jsonb) on conflict(id) do update set content=pg_temp.merge_archive_arrays(public.people.content,excluded.content),alt_name=coalesce(public.people.alt_name,excluded.alt_name),updated_at=now();
