-- Existing place: wahlagarden
update public.places set content=pg_temp.merge_archive_arrays(content,'{"aliases":["Wahlagården","Valagården","Välagården","Wahlagård","Valagård","Träslöf Valagård","Jon Nilsgård","John Nilsgård","Jöns Nilsgård","Joen Nilsgård","N:o 5 Jon Nilsgård","Wahlagården Jon Nilsgård","Träslöv N:o 5","Jon Nils Hemman","Joen Nilsgård","Träslöv nr 5 Valagården","Träslöv 5:3 Valagården","Träslöv 5:6","Träslöv 5:7","Hwalagården","Joen Nielsons gård"],"facts":[["Gårdsidentitet","Jöns/Jon/Joen Nilsgård, Jon Nils Hemman, Wahlagården, Valagården och Välagården behandlas som samma gårdsmiljö i Träslöv nr 5."],["Säker huvudkedja","Mårten Andersson + Helena Jönsdotter → Anna Mårtensdotter + Olof Andersson → Anna Olofsdotter + Börje Pehrsson → Bengta Börjesdotter + Bengt Olofsson."],["Källstatus","Stark gårdskontinuitet från 1762 till 1820. Äldre spår omkring 1700 är viktiga men fortsatt källkritiska."],["1915","Lokalundersökningsblanketten anger Bengt Nilsson d.ä. som ägare och beskriver Valagård som cirka 12 hektar stort jordbruk."],["Källnivåer","Originalhandlingar och kontrollerade kyrkböcker hålls åtskilda från familjeavskrifter, register, sekundär forskning och hypoteser."],["Äldre namn","Hallands Släktforskarförenings register anger Joen Nilsgård som namn år 1645 för Träslöv nr 5."],["Jordnatur","En familjeavskrift uppger klosterhemman 1649 och senare kronohemman. Bakomliggande originalkälla är ännu inte identifierad."],["Landsbeskrivning 1729","Familjens avskrift beskriver Joen Nielsons gård som ett kronohemman om 3/4 mantal, delat mellan Swen Andersson och Anders Mårtenssons änka med 3/8 mantal vardera."],["Laga skifte 1839","Familjens avskrift anger tre åbor: Börje Larsson 3/16 mantal, Nils Börjesson 3/16 mantal och Bengt Olsson 3/8 mantal."],["Gårdsmiljö 1857","Familjeanteckningarna anger 37 personer i sex hushåll samt ett jordtorp och en backstuga inom Träslöv nr 5."],["Byggnader 1866","Familjens avskrift för Träslöv 5:6 beskriver delning av ett förfallet halmtäckt boningshus och ladugård mellan Petter Anders Svensson och Bengt August Nilsson."],["Ekonomiska handlingar","Skuldebrev och inteckningar 1888-1912 berör andelar i Träslöv nr 5, men varje andels exakta samband med familjens del av Valagården är inte slutligt klarlagt."],["Jordbruk 1915","Valagård omfattade 12,00 hektar, varav 11,50 hektar odlad jord. Djurbeståndet omfattade bland annat två arbetshästar, ett föl, ungnöt, kalv, grisar och 25 höns."],["Fastighetsdelar","Materialet nämner bland annat Träslöv 5:3, 5:6 och 5:7. De ska inte behandlas som identiska utan fortsatt kontroll av avstyckningar och ägogränser."],["Arrende 1958-1963","Originalkontraktet visar att Lars Emil Bengtsson ägde Träslöv 5:7 och arrenderade ut fastigheten till brorsonen Harry Bengtsson för 900 kronor per år."],["Tidigaste originalspår för familjen","Nils Mårtenssons födelse- och dopnotis 1740 placerar med hög sannolikhet Mårten Anderssons och Helena Jönsdotters familj vid Jöns Nilsgården"],["Tre generationer 1773–1788","Helena Jönsdotter, Anna Mårtensdotter och Anna Olofsdotter återfinns under samma gårdsrubrik Jon Nils gård"],["Modern familjeövergång","Axel Harry och Karin flyttade enligt familjeberättelsen till Valagården 1985; gården överläts till Gerd 1990"]],"story":["Valagård/Wahlagården är en av de viktigaste gårdsmiljöerna i morfars Bengtssonlinje. I källorna växlar namnen mellan Jöns Nilsgård, Jon Nilsgård, Joen Nilsgård, Wahlagården, Valagården och Välagården, men v125-underlaget behandlar dem som samma gårdsenhet i Träslöv nr 5.","Den säkra släktkedjan börjar med att Mårten Andersson och Helena Jönsdotter är belagda vid Jöns Nilsgård genom Mårtens död och bouppteckning 1762. Deras dotter Anna Mårtensdotter gifter sig med Olof Andersson från Dagsås och dottern Anna Olofsdotter föds på Jon Nilsgård 1767.","Gården fortsätter sedan genom Anna Olofsdotter och Börje Pehrsson till Bengta Börjesdotter. När Bengta gifter sig med Bengt Olofsson 1813 anges hon komma från Wahlagården, och barnens födelsenotiser 1814-1820 visar att Wahlagården och Jon Nilsgård används parallellt för samma miljö.","Det äldre materialet kring N:o 42 Jon Nils Hemman och Träslöv N:o 5 för gårdshistorien bakåt mot 1600- och tidigt 1700-tal. Där finns starka gårdsspår, men vissa personkopplingar ska hållas som hypoteser tills fler originalkällor är säkrade.","Den nya Valagården-mastern skiljer uttryckligen mellan originalhandlingar, familjens avskrifter, index och register, sekundär forskning samt hypoteser. Gårdens historia redovisas därför med olika säkerhetsnivåer: en senare gårdsanknytning innebär exempelvis inte automatiskt att personen föddes där eller ägde marken.","Gårdsregistret för Träslöv nr 5 anger Joen Nilsgård som äldre namn år 1645. Familjens bevarade gårdsanteckningar uppger dessutom att gården var klosterhemman 1649 och senare kronohemman. Den uppgiften är värdefull men vilar ännu på en familjeavskrift vars bakomliggande original måste identifieras.","Omkring år 1700 visar det äldre materialet två skilda hushållsgrupper vid Jon Nils hemman. I den första finns Anders Andersson, Karin Olsdotter/Olofsdotter och barnen Olof, Börje och Kirsti/Kerstin Andersdotter. Den femåriga personen har tidigare lästs som Mårten Andersson, men den läsningen är korrigerad. I en andra grupp finns Börje Nilsson med hustru och flera barn. Grupperna visar gårdsmiljön men får inte utan ytterligare belägg kopplas till huvudlinjens Mårten Andersson.","Familjens avskrift av 1729 års landsbeskrivning ger en konkret bild av Joen Nielsons gård som ett kronohemman om tre fjärdedels mantal, delat mellan två åbor. Där fanns två stugor med förstugor, härbärgen, brygghus, uthus, torvhus och vagnskjul, en liten trädgård med äppelträd samt två kålhagar. Swen Andersson uppges ha tillträtt sin andel 1699 och Anders Mårtenssons änka sin andel 1722. Uppgifterna behöver fortfarande kontrolleras mot landsbeskrivningens original.","Den första säkra och tydligt dokumenterade kopplingen för den direkta linjen är Mårten Andersson och Helena Jönsdotter vid Jöns Nilsgård 1762. Därefter kan boende- och släktkontinuiteten följas genom Anna Mårtensdotter, Anna Olofsdotter och Bengta Börjesdotter till Bengt Olofsson och barnen. Mönstret talar för att gårdsanknytningen kan ha följt kvinnolinjen, men det bevisar inte privat ägande eller exakt brukningsrätt.","Kartavskrifter från 1823 och 1840 visar flera gårdslägen inom Träslöv nr 5. Inför laga skiftet 1839 brukade Börje Larsson och Nils Börjesson vardera tre sextondels mantal, medan Bengt Olsson brukade tre åttondels mantal. Nils Börjesson och Bengt Olsson uppges ha haft en gård tillsammans, medan Börje Larssons bebyggelse låg avskilt. År 1857 fanns enligt familjeanteckningarna 37 personer i sex hushåll samt jordtorp och backstuga.","En familjeavskrift av en förrättning den 4 juli 1866 beskriver Valagården Träslöv 5:6 i ovanlig detalj. Det halmtäckta boningshuset var 61 fot långt och rymde stuga, förstuga, härbärge, kammare och kök. Byggnaderna var förfallna och delades mellan Petter Anders Svensson och Bengt August Nilsson. Tolkningen att Petter skulle flytta och Bengt August stanna kvar är stark men behöver jämföras med originalhandlingen.","Ekonomiska handlingar visar flera skilda andelar i Träslöv nr 5. Alfred Sundgren intecknade 3/64 mantal 1888. Bengt August Nilsson den äldre tog 1901 ett lån på 1 600 kronor med en indirekt säkerhet knuten till 3/64 mantal Jöns Nilsgård; räntebetalningar kan följas till 1911. Handlingarna belyser gårdens ekonomi men bevisar inte att alla nämnda andelar motsvarade samma brukningsdel.","Lokalundersökningen 1915 visar Valagård som ett intensivt brukat jordbruk på 12 hektar, nästan helt odlat. Där odlades spannmål, potatis, foderrotfrukter, hö och grönfoder, och gården hade hästar, nötkreatur, grisar och höns. Bengt Nilsson den äldre står i ägarfältet, men blanketten avgör inte om Sara Britta Andersdotter hade en juridisk andel.","Familjens material från 1920-talet visar flera åbor och yrkesarbetande barn inom den äldre gårdsmiljön. Ett originalskuldebrev från 1928 visar dessutom att Lars Emil Bengtsson, under namnet Emil Bengtsson och adressen nr 5 Träslöv, erkände en skuld på 3 000 kronor till brodern Sven Adolf Bengtsson i Klastorp. Räntan anges löpa från 1920, vilket kan tyda på ett äldre lån men ännu är en tolkning.","Svenska Gods och Gårdar 1939 och 1946 återger två olika ägarlängder för Träslöv 5:3 Valagården. En går genom Bengt Olsson, Nils Bengtsson, Bengt August Nilsson och Lars Emil Bengtsson; en annan genom Karl Andersson, Emil Johansson, Algot Leonard Andersson och Sten Andersson. Skillnaden bevaras som en öppen fråga och får inte jämnas ut utan kontroll av utgåvor, brukningsdelar och tidsskeden.","Arvskiftet efter Alma Josefina Bengtsson 1955 placerar Lars Emil Bengtsson på Valagården och dokumenterar syskon och amerikanska arvingar. Ett originalkontrakt från 1958 visar sedan att Lars Emil, som skrev sig Emil Bengtsson, ägde Träslöv 5:7 och arrenderade ut fastigheten till brorsonen Harry Bengtsson till 1963. Emil behöll Smedlyckan bakom ladan för eget bruk, medan Harry fick bruka jorden och använda lada och loge.","V125 flyttar det tidigaste nuvarande originalspåret för den direkta familjen på gården tillbaka till 1740. Sonen Nils föds och döps som barn till Mårten Andersson och Helena Jönsdotter, och gårdsfrasen kan med hög sannolikhet läsas Jöns Nilsgården.","Husförhöret 1773–1788 visar tre generationer av den direkta kvinnolinjen under samma gårdsrubrik: änkan Helena Jönsdotter, dottern Anna Mårtensdotter och dotterdottern Anna Olofsdotter. Det bevisar gemensam gårdsmiljö men inte nödvändigtvis samma bostadshus.","Den handskrivna familjeberättelsen för gårdens historia fram till nutid: Axel Harry och Karin återvände 1985 till Valagården, som uttryckligen kallades släktgården, och 1990 överläts den enligt berättelsen till dottern Gerd. Juridisk form och exakta datum behöver fastighetsakter."],"timeline":[["ca 1699-1702","Daterade anteckningar knyter Sven Andersson, Inger Olsdotter och en möjlig tidig familjemiljö till Valagård/Jon Nils Hemman. Detta är ett viktigt äldre gårdsspår men inte hela vägen låst till huvudlinjen."],["1700","N:o 42 ''Jon Nils Hemman i Träslöf'' bedöms höra till Jon/Jöns/Joen Nilsgård = Wahlagård/Valagård. Viktig korrigering: den femåriga personen läses som Kirsti/Kerstin Andersdotter, inte Mårten Andersson."],["1707","En post för Träslöv N:o 5 har identifierats som tidigt belägg för gårdsnumret bakom Jöns/Jon Nilsgård och senare Wahlagården/Valagården. Personerna i utsnittet är ännu inte säkert identifierade."],["1762-07-27","Mårten Andersson dör vid Jöns Nilsgård av bröstfeber. Bouppteckningen 1762-10-21 nämner änkan Helena Jönsdotter och åtta barn."],["1765-02-10","Anna Mårtensdotter från Träslöv Jön Nilsgård gifter sig med Olof Andersson från Dagsås. Olof kommer därmed in i gårdsmiljön genom äktenskapet."],["1767-06-17","Anna Olofsdotter föds vid Jon Nilsgård som dotter till Olof Andersson och Anna Mårtensdotter."],["1787-1800","Husförhör placerar Olof Andersson, Anna Mårtensdotter, Anna Olofsdotter och Börje Pehrsson i hushållsmiljön vid N:o 5 Jon Nilsgård."],["1790-12-26","Anna Olofsdotter från Träslöf Valagård gifter sig med Börje Pehrsson från Klastorps Buragård."],["1800-10-13","Bouppteckningen efter Helena Jönsdotter förrättas vid N:o 5 Jon Nilsgård och nämner dottern Anna, gift med Olof Andersson."],["1813-1820","Namnen Wahlagården och Jon/John Nilsgård används parallellt: Bengta Börjesdotter anges från Wahlagården 1813, barn föds vid Wahlagård 1814-1816 och vid John/Jon Nilsgård 1818-1820."],["1915-08-31","Lokalundersökningsblanketten för Valagård anger Bengt Nilsson d.ä. som ägare. Gården omfattar cirka 12 hektar, med omkring 11,5 hektar odlad jord och tydlig spannmåls-, potatis-, foderväxt- och höproduktion."],["1645","Gårdsregistret anger Joen Nilsgård som äldre namn för Träslöv nr 5."],["1649","Familjens avskrift uppger att gården var klosterhemman och senare blev kronohemman; originalkällan återstår."],["1718","Familjens gårdsanteckningar nämner ''Swen Hwahl och Ingri av Hwalagården''. Identifikationen med Swen Andersson och Inger Olsdotter är ännu en hypotes."],["1729","Familjens avskrift av landsbeskrivningen visar två åbor på Joen Nielsons gård och beskriver byggnader, trädgård, åker, äng och samfälld betesmark."],["1731-04-25","Mårten Andersson och Helena Jönsdotter vigs. Notisen anger Träslövs by respektive Skultagården och är inte ett säkert Valagårdsbelägg."],["1740-08-08","Nils Mårtensson anges i sekundär forskning vara född på Valagård; originalnotisen är ännu inte kontrollerad."],["ca 1756-1759","Husförhör under Jon Nilsgård visar Mårten Anderssons och Börge Anderssons hushåll. En tidigare marginaltolkning om flytt till Walegård är korrigerad till sannolikt Falkenberg."],["1812-1829","Husförhöret Träslöv AI:5 har rubriken ''Wahlagården Jon Nilsgård'', ett direkt belägg för parallell namnanvändning."],["1823","Familjens handritade kartavskrift visar flera husgrupper på Träslöv 5 Jon Nilsgård."],["1839","Förarbetena till laga skiftet beskriver tre åbor och gårdens tre brukningsandelar."],["1840","En kartavskrift markerar gårdslägen för Bengt Olsson, Nils Börjesson och Börje Larsson."],["1857","Familjeanteckningarna anger 37 personer i sex hushåll, ett jordtorp och en backstuga inom Träslöv nr 5."],["1866-07-04","Boningshus och ladugård på Träslöv 5:6 delas mellan Petter Anders Svensson och Bengt August Nilsson enligt en familjeavskrift."],["1888-05-09","Alfred Sundgren belånar 3/64 mantal kronoskatte Träslöv nr 5; dokumentet fastställer inte vilken senare brukningsdel andelen motsvarar."],["1901-04-04","Bengt August Nilsson den äldre utfärdar ett skuldebrev på 1 600 kronor. Räntor kvitteras 1902-1911."],["1920","Familjens församlingsboksutdrag visar flera åbor och hushåll inom den äldre gårdsmiljön."],["1928-11-12","Lars Emil Bengtsson erkänner under namnet Emil Bengtsson en skuld på 3 000 kronor till brodern Sven Adolf Bengtsson."],["1939-1946","Svenska Gods och Gårdar återger olika ägarlängder för Träslöv 5:3 Valagården; skillnaden är inte löst."],["1954-10-15","Alma Josefina Bengtsson avlider enligt originalutdraget ur arvskiftet."],["1955-01-12","Arvskiftet efter Alma dokumenterar syskonen, amerikanska arvingar och Lars Emil Bengtssons bosättning på Valagården."],["1958-03-25","Lars Emil Bengtsson tecknar under namnet Emil Bengtsson arrendeavtal om Träslöv 5:7 med brorsonen Harry Bengtsson."],["1958-04-01–1963-04-01","Harry Bengtsson arrenderar Träslöv 5:7 för 900 kronor per år. Emil behåller Smedlyckan bakom ladan."],["1740-08-08","Nils Mårtensson föds; originalnotisen har en starkt läst gårdsfras Jöns Nilsgården."],["1773–1788","Tre generationer av direktlinjen återfinns under rubriken Jon Nils gård."],["1985","Axel Harry och Karin flyttar från Korsberg till Valagården enligt familjeberättelsen."],["1990","Valagården överlåts enligt familjeberättelsen till Gerd Elisabeth Bengtsson."]],"sources":["Träslöv (N) CI:4 (1747-1798), Bild 490 / Sida 87: Anna Olofsdotters födelse 1767.","Träslöv (N) CI:4, Bild 1180 / Sida 223: Olof Anderssons och Anna Mårtensdotters vigsel 1765.","Träslöv (N) CI:4, Bild 1230 / Sida 233: Börje Pehrssons och Anna Olofsdotters vigsel 1790.","Träslöv (N) CI:4, Bild 1410 / Sida 267: Mårten Anderssons död 1762.","Träslöv (N) CI:5 (1799-1825), Bild 109 / Sida 211: Nils Bengtssons födelse 1814.","Träslöv (N) CI:5, Bild 130 / Sida 251: Anders Bengtssons födelse 1816.","Träslöv (N) CI:5, Bild 208 / Sida 407: Bengt Olofssons och Bengta Börjesdotters vigsel 1813.","Träslöv (N) AI:3 (1787-1800), Bild 85 / Sida 111: N:o 5 Jon Nilsgård.","Träslöv (N) AI:5 (1812-1829), Bild 174 / Sida 37: ''Wahlagården Jon Nilsgård''.","Himle häradsrätt FIIb:3 (1760-1789), originalsid 9: Mårten Anderssons bouppteckning 1762.","Himle häradsrätt FIIa:11 (1800-1802): Helena Jönsdotters bouppteckning 1800.","IMG_6517.HEIC, IMG_6518.HEIC och IMG_6519.HEIC: familjens gårdsanteckningar och kartavskrifter, granskade 2026-08-31.","IMG_6524.HEIC och IMG_6525.HEIC: familjeavskrift om Valagården Träslöv 5:6 och byggnadsdelningen 1866.","otydligt3.HEIC, otydligt1.HEIC och otydligt2.HEIC: kopia av Alfred Sundgrens skuldebrev 1888 och överlåtelsepåskrift 1912.","otydligt.HEIC och otydligt4.HEIC: kopia av Bengt August Nilssons skuldebrev 1901 och ränteanteckningar 1902-1911.","anteckning om sven adolf.HEIC: originalskuldebrev mellan Lars Emil och Sven Adolf Bengtsson, 1928-11-12.","Arvskifte efter Alma 1955.HEIC: originalutdrag efter Alma Josefina Bengtsson, förrättat 1955-01-12.","IMG_6532.HEIC: originalarrendekontrakt mellan Lars Emil Bengtsson och Harry Bengtsson, daterat 1958-03-25.","Leif Lundquist, Halländsk antavla 4, Hallands Släktforskarföreningen.","Hallands Släktforskarförenings gårds- och ortnamnsregister.","Morfars master v125, daterad 2026-09-01: originalnotis för Nils Mårtensson 1740 och husförhör 1773–1788.","Mormors handskrivna levnadsberättelse och släktblad, mottagna 2026-08-31; sekundära familjekällor."],"uncertainties":["Familjeuppgiften om klosterhemman 1649 behöver spåras till bakomliggande originalkälla.","Swen Andersson, Inger Olsdotter och Karin Svensdotter är sekundärt knutna till gården omkring 1699-1702 och behöver verifieras i original.","1718 års anteckning om Swen Hwahl och Ingri behöver återfinnas i original.","Familjens avskrift av 1729 års landsbeskrivning behöver kontrolleras ord för ord mot originalet.","Mårten Anderssons och Helena Jönsdotters första inflyttning till Jon/Jöns Nilsgård är ännu inte fastställd.","Nils Mårtenssons uppgivna födelse på Valagård 1740 är sekundär tills födelsenotisen har kontrollerats.","Karin Börgesdotter som uppges ha avlidit på Valagård 1705 får inte sammanblandas med den 13-åriga Karin Börgesdotter i gruppen omkring 1700.","Originalkartorna 1823 och 1840 behöver identifieras för säker placering av hus och ägogränser.","Den bakomliggande källan till uppgiften om 37 personer och sex hushåll 1857 återstår.","Originalet till förrättningen 1866 behöver hittas; tolkningen att Petter Anders Svensson flyttade och Bengt August Nilsson stannade kvar är ännu inte slutbevisad.","Sambandet mellan fastighetsbeteckningarna Träslöv 5:3, 5:6 och 5:7 behöver klarläggas.","Alfred Sundgrens intecknade 3/64 mantal 1888 kan inte utan vidare likställas med Bengt August Nilssons brukningsdel.","Det exakta slutbetalningsdatumet för Bengt August Nilssons skuld är otydligt.","De två olika ägarlängderna för Träslöv 5:3 i Svenska Gods och Gårdar måste jämföras med originalutgåvorna.","Arvskiftet 1955 nämner ingen fastighet och visar därför inte i sig någon övergång av Valagården.","Arrendets fortsättning eller upphörande efter 1 april 1963 är inte känd.","Smedlyckans exakta läge bakom ladan behöver identifieras på karta.","Skillnaden mellan skuldebrevets datering 1928 och räntans startår 1920 behöver förklaras.","Amerikaspåren för Anders Gustaf, Karl Oskar och Johan Albin Bengtsson behöver beläggas med utflyttningslängder och amerikanska källor.","Full arkivsignatur för Nils Mårtenssons födelsenotis och husförhöret 1773–1788 återstår.","Gårdsövergångarna 1985 och 1990 behöver verifieras i lagfart, köpebrev, gåvobrev eller fastighetsregister."]}'::jsonb),updated_at=now() where id='wahlagarden';
-- Existing place: klockaregarden
update public.places set content=pg_temp.merge_archive_arrays(content,'{"aliases":["Klockaregården","Klockargården","Lars Tungård","Träslöv 1","Träslöv nr 1","Lars Ringsgård","Lars Trulsgård"],"relatedPersonIds":["jons_polin_1682","karin_helgesdotter_1685","beata_jonsdotter_polin","helena_jonsdotter_1713","petter_jonsson_polin","kerstin_jonsdotter_polin_1725","anna_jonsdotter_polin_1728","bengt_ehn_1726","anne_maja_lomberg_1754","johannes_ehn_1771"],"facts":[["Gårdsidentitet","Hallands Släktforskarförenings gårdsregister anger Träslöv nr 1 = Lars Tungård, med bruksnamnet Klockaregården."],["Viktig åtskillnad","Klockaregården och Prästgården är två olika platser. Kyrkobokens innehållsförteckning samlar material från båda i ett gemensamt specialavsnitt, men det gör dem inte till samma gård."],["Polin-koppling","Jöns Andersson Polin kom till klockaretjänsten i Träslöv 1703. Gården är därför ett naturligt men ännu inte slutbevisat bostadsspår för familjen."],["Arbetsperiod","Den viktigaste perioden att kartlägga är 1704-1715 och därefter fram till att Jöns lämnade tjänsten efter 1747."],["Mantalslängd 1731","Det första gårdsblocket i Träslövs mantalslängd förefaller motsvara Klockaregården, men namnen är ännu för svårlästa för att Jöns Polin ska identifieras säkert där."],["Kyrkoboksavsnitt","Ett särskilt födelse- och dödboksavsnitt gäller Klockaregården samt den separata Prästgården. Senare närbilder visar starka Polin-familjeposter."],["Polin-familjen","Beata 1707, Helena 1713 och Petter 1721 är starka poster. Kerstin/Kirsti 1725 och Anna 1728 är sannolika sidospår med lägre säkerhet."],["J. A. Polin 1707","Signaturen ''Finis hujus Anni. J. A. Polin'' vid årets slut är ett mycket starkt spår efter Jöns Andersson Polin och hans kyrkliga skrivarroll."],["Faddermiljö","Nätverket omfattar Varberg, Lunden, Klastorp och möjliga Polin/Bolin-personer som Lars, Agneta och Greta."],["N:o 38-korrigering","N:o 38 är Börge Anders hemman och får inte användas som synonym för Klockaregården. Klockaregården ska sökas genom gårdsnamnet, Träslöv nr 1, klockartiteln eller annan oberoende uppgift."],["Källstatus","Gårdsidentiteten Träslöv nr 1/Lars Tungård/Klockaregården stöds av gårdsregistret. Polin-familjens exakta boende och flera fadderläsningar behöver fortsatt originalkontroll."],["Namn enligt gårdsblad","Träslöv nr 1 Klockaregården, även Lars Ringsgård och Lars Trulsgård; Lars Tungård kommer från ett separat register"],["Jordnatur","1/4 mantal krono; Jöns Paulin anges som åbo 1729 i en sekundär avskrift av landsbeskrivningen"],["Klockarföljd","Lars Ring, Jöns Polin, Bengt Ehn och den fortsatta Ehn-linjen enligt lokalt gårdsblad; exakta tjänsteår behöver originalkontroll"],["Originalstöd 1773–1788","Husförhör visar N:o 1 Klockaregården med klockaren Bengt Ehn, Anna Polin, Anna/Anne Maja Lomberg och sonen Johannes"],["Byggnader 1729","Stuga, två härbärgen, liten kammare, loge, korn- och höladar, stall, fårhus, portskjul och ett svårläst ''hiemelhus''"],["Odling 1729","Kålhage med små äppelträd, stengärdesgårdar och ekbuskar på ängen enligt gårdsbladets avskrift"],["Besiktning 1839","Äldre manhus i försvarligt skick, delvis ny ladugård och en fruktträdgård intill kyrkogårdsmuren"],["Senare brukare","Anders Svensson arrendator 1910 och 1920; H. J. Henriksson köpare 1949, Olof Larsson 1961 och Peter Karlsson köpare av tomten 1984 enligt gårdsbladet"]],"story":["Klockaregården är en egen gård i Träslöv och ska hållas helt åtskild från Prästgården. Gårdsregistret identifierar Träslöv nr 1 som Lars Tungård med bruksnamnet Klockaregården. Ett original där namnformerna står sida vid sida bör fortfarande jämföras, men identifikationen är betydligt starkare än den äldre hypotesen kring N:o 38.","Gården är central för Polin-forskningen eftersom Jöns eller Jonas Andersson Polin kom till klockaretjänsten i Träslöv 1703. Efter vigseln med Karin Helgesdotter 1705 kan Klockaregården ha blivit familjens tjänste- eller bostadsmiljö. Det är ännu inte slutligt bevisat att hela familjen bodde där, så personkopplingen ska beskrivas som starkt platsspår snarare än säker bostadsadress.","Bokens innehållsförteckning pekar ut ett särskilt kyrkoboksavsnitt för Klockaregården samt Prästgården. Det betyder att källmaterial från två olika platser har samlats i samma avsnitt. En enskild notis får därför inte automatiskt tillskrivas Klockaregården utan att text, titel, person eller annan omständighet visar det.","Senare och tydligare närbilder har korrigerat det äldre forskningsläget. Beata Polins födelse den 15 april och dop den 17 april 1707 är nu en mycket stark originalkandidat. Helena Jönsdotters födelse natten mellan 6 och 7 oktober och dop den 8 oktober 1713 är en direkt originalkälla till huvudlinjen. Petters post 1721 är också stark, medan Kerstin/Kirsti 1725 och Anna 1728 förs mer försiktigt.","Vid slutet av 1707 års kyrkoboksanteckningar står sannolikt ''Finis hujus Anni. J. A. Polin''. Initialerna och det ovanliga namnet passar Jöns Andersson Polin mycket väl. Signaturen kan vara hans egen och antyder att han deltog i kyrkobokens förande eller sammanställning, men exakt hand och arbetsinsats är ännu inte absolut bevisade.","Fadderkretsen ger gårdsmiljön ett större socialt sammanhang. Lars Polin förekommer sannolikt vid Beatas dop 1707. Vid Helenas dop 1713 syns bland andra Jöns Grimberg, Mathias Höök, Olof Börgesson i Lunden, Anders Gillberg/Cillberg och Elisabet Bruhn samt personer från Varberg. År 1721 återkommer Klastorp, Lunden och möjliga Greta eller andra Polin/Paulin-personer.","Mantalslängden 1731 är viktig eftersom gårdsföljden sannolikt börjar med Träslöv nr 1 Klockaregården. Namnen i det första blocket är dock ännu för svårlästa för att Jöns ska föras in som säker boende. Jämförelse med 1730 och 1732 kan visa vem som brukade gården och hur tjänste- eller hushållsrollen förändrades.","En tidigare arbetsidé försökte koppla N:o 38 till Klockaregården. Den är korrigerad: N:o 38 är Börge Anders hemman och hör till ett annat gårdsspår. Klockaregården ska följas separat genom Lars Tungård, Träslöv nr 1, klockartiteln och Polin-familjens uttryckliga källspår.","Ett lokalt gårdsblad identifierar uttryckligen Klockaregården, Lars Ringsgård och Lars Trulsgård som samma gårdsmiljö i Träslöv nr 1. Lars Tungård bevaras som en separat registervariant. Bladet är en sekundär sammanställning och de äldre handlingarna behöver återfinnas i original.","Landsbeskrivningen 1729 återges med Jöns Paulin som åbo på ett fjärdedels mantal krono. Hushållet bestod av en hustru, två onamngivna döttrar och en dräng. Helena är en rimlig men inte säker kandidat till en av döttrarna.","Gårdsbladets byggnadsbeskrivning gör miljön konkret: en stuga, förvaringshus, liten kammare, loge, lador, stall och fårhus omgavs av kålhage, små äppelträd och stengärdesgårdar. Uppgifterna beskriver klockarhushållets vardagsmiljö men ska jämföras med 1729 års original.","Husförhöret 1773–1788 ger oberoende originalstöd för nästa generation. Klockaren Bengt Ehn och hustrun Anna Polin återfinns på N:o 1 Klockaregården tillsammans med den senare hustrun Anna/Anne Maja Lomberg och sonen Johannes.","Besiktningen 1839 placerar gårdens mindre fruktträdgård direkt vid kyrkogårdsmuren. Senare notiser följer miljön från arrendegård 1910–1920 till köp av gård eller tomt 1949, 1961 och 1984."],"timeline":[["1703","Jöns Andersson Polin kommer till klockaretjänsten i Träslöv."],["1704-07-10","Jöns Polin förekommer sannolikt som fadder vid Skultagården. Det visar ett tidigt lokalt nätverk men inte bosättning på Klockaregården."],["1705-03-19","Jöns Polin och Karin Helgesdotter vigs. Tiden därefter är prioriterad för att fastställa familjens eventuella bosättning på Klockaregården."],["1707-04-15/17","Mycket stark post för dottern Beatas födelse och dop i specialavsnittet."],["1707","Året avslutas med den sannolika signaturen ''J. A. Polin'', ett starkt indicium på Jöns kyrkliga skrivarroll."],["1713-10-06/08","Helena Jönsdotter föds under natten mellan 6 och 7 oktober och döps 8 oktober som klockarens dotter."],["1721-10-31/11-05","Stark post för sonen Petters födelse och dop; sekundärmaterial placerar honom vid Klockaregården."],["1725-08-12/15","Sannolik post för dottern Kerstin/Kirsti. Möjlig Mårten Andersson i fadderlistan är ännu obekräftad."],["1728-01-21/26","Dottern Anna föds och döps i den fortsatta kyrkliga miljön."],["1731","Mantalslängdens första gårdsblock förefaller avse Klockaregården, men Jöns Polin är ännu inte säkert läst där."],["efter 1747","Jöns lämnar klockaretjänsten till mågen Bengt Ehn."],["1758-05-24","Jöns Polin dör; dödsnotisen beskriver sannolikt hans gravplats vid Träslövs kyrka."],["1729","Sekundär avskrift placerar Jöns Paulin som åbo på Lars Trulsgård/Klockaregården och beskriver hushåll, byggnader och odling."],["1773–1788","Originalhusförhör visar Bengt Ehn och Anna Polin på N:o 1 Klockaregården."],["1839","Besiktning inför laga skifte beskriver byggnader och fruktträdgård intill kyrkogårdsmuren."],["1910–1920","Anders Svensson anges som arrendator enligt gårdsbladet."],["1949","H. J. Henriksson köper gården enligt gårdsbladet."],["1961","Olof Larsson köper gården enligt gårdsbladet."],["1984","Peter Karlsson köper tomten enligt gårdsbladet."]],"sources":["Hallands Släktforskarförenings gårdsregister: Träslöv nr 1 = Lars Tungård, bruksnamn Klockaregården.","Träslövs mantalslängd 1731, gårdsföljden omkring sidorna 700-701; första gårdsblocket behöver fortsatt transkription.","Träslövs kyrkoboks specialavsnitt för Klockaregården samt Prästgården, med granskade poster 1701-1728.","Externt ortnamnsregister till 50 halländska antavlor, med Beata Jönsdotter Polin och Petter Jönsson Polin placerade vid Träslöv Klockaregården.","Jöns Andersson Polins vigselnotis 1705, Helenas födelse- och dopnotis 1713 samt Jöns dödsnotis 1758.","historia klockaregård.HEIC, lokalt maskinskrivet gårdsblad mottaget 2026-08-31; sekundär källa.","Riksarkivets husförhörslängd 1773–1788, N:o 1 Klockaregården; exakt volym, bild och sida återstår.","Carl Sjöström, Göteborgs nation i Lund 1669–1906 (1907), s. 198."],"uncertainties":["Klockaregården och Prästgården är olika platser; poster i deras gemensamt rubricerade kyrkoboksavsnitt måste fördelas källkritiskt.","Ett original som uttryckligen visar namnformerna Lars Tungård och Klockaregården sida vid sida bör fortfarande kontrolleras.","Jöns och Karin är ännu inte slutligt originalbelagda som boende på Klockaregården trots den starka yrkes- och familjekopplingen.","N:o 38 får inte kopplas till Klockaregården; det är Börge Anders hemman.","Lars Polins släktskap med Jöns samt läsningarna Agneta Polin, Greta Polin och ytterligare Polin/Paulin-personer är inte bekräftade.","Den möjliga Mårten Andersson i 1725 års fadderlista behöver prioriterad omläsning.","Landsbeskrivningen 1729, besiktningen 1839 och den senare ägarlängden behöver kontrolleras mot bakomliggande original.","De två onamngivna döttrarna i hushållet 1729 får inte automatiskt identifieras som Helena eller någon särskild syster."]}'::jsonb),updated_at=now() where id='klockaregarden';
-- Existing place: skultagarden
update public.places set content=pg_temp.merge_archive_arrays(content,'{"aliases":["Skultagården","Skultagård","N:o 39 Skultagården","Börje Andersgård","Träslöv nr 2"],"relatedPersonIds":["helge_svensson","karin_helgesdotter_1685","helena_jonsdotter_1713"],"facts":[["Gårdsidentitet","Originalsidan är rubricerad N:o 39 Skultagården och ska hållas åtskild från Valagården utan särskilt källstöd."],["Nutida uppgift","Användaren uppger att Skultagården är närliggande Valagården och finns kvar än idag."],["Tidigt hushåll","Gården visar bland annat Börge Andersson, Inger Larsdotter, Lars Jönsson, Börta/Brita Börgesdotter och flera barn i äldre hushållsmiljö."],["Polin-spår","Jöns Polin läses med hög sannolikhet som fadder/vittne i en kristningsnotis 1704-07-10."],["Direkt släktkoppling","Helena Jönsdotter, dotter till Jöns Polin och Karin Helgesdotter, anges som piga från Skultagården vid vigseln 1731."],["Fasta namn och nummer","Träslöv nr 2 Skultagården, även Börje Andersgård; äldre N:o 39 är kyrkoboksvolymens interna ordningspost"],["Historisk funktion","Sekundärt gårdsblad beskriver en äldre prästgård som senare blev borgmästarboställe under Varbergs stad"],["Jordnatur 1729","Ett mantal krono, delat mellan Börge Björnsson och Anders Larsson med ett halvt mantal vardera"],["Boskapspest","En kyrkoboksavskrift anger att boskapssjukan började på Skultagården i oktober 1747 och spreds i pastoraten"],["Torp 1823","Wästra Torp, Södra Lid, Badstubrå och Badstukärr enligt lokalt gårdsblad"],["Laga skifte 1839","Änkorna Maria Persdotter och Pernilla Olsdotter brukade var sitt halvt mantal"],["Arbetsplats 1920","Sex namngivna statdrängar, jordbruksarbetare och en smed fanns på gården med sina familjer enligt sammanställningen"],["Omfattning 1942","150 tunnland åker och 10 tunnland utmark enligt gårdsbladet; original och modern omräkning återstår"]],"story":["Skultagården är en egen gårdsmiljö i Träslöv och ska inte blandas ihop med Valagården/Wahlagården. V102 gör denna åtskillnad viktig, eftersom flera personer rör sig i samma lokala nätverk utan att gårdarna därför blir samma plats.","Gårdssidan innehåller hushålls- och åldersuppgifter samt löpande notiser om dop, vigslar och begravningar från omkring 1690 till 1713. Den visar en äldre Börge-, Lars- och Jöns-miljö innan Polin-kopplingen blir tydlig.","Det mest intressanta Polin-spåret är 1704-07-10, där Jöns Polin sannolikt förekommer som fadder eller vittne i Skultagårdens material. Det bevisar inte att han bodde där, men visar sannolikt att han ingick i gårdens sociala nätverk redan året före vigseln med Karin Helgesdotter.","Skultagården blir senare viktig genom att Helena Jönsdotter anges som piga därifrån när hon gifter sig med Mårten Andersson 1731. Kopplingen mellan Helge Svenssons familj, Polin-familjen och Skultagården ska därför fortsätta följas kronologiskt.","V125 identifierar gården som Träslöv nr 2 Skultagården, även Börje Andersgård. Den äldre beteckningen N:o 39 hör till kyrkoboksvolymens interna ordning och är inte ett konkurrerande fastighetsnummer.","Ett lokalt gårdsblad beskriver Skultagården som en tidigare prästgård som övergick till borgmästarboställe. Karl XI ska ha bekräftat ordningen 1683, och gårdens avkastning knöts senare till Varbergs stads ekonomi. Detta är sekundär lokalhistorik tills bakomliggande handlingar har lokaliserats.","År 1729 beskrivs Skultagården som ett kronohemman om ett mantal, delat mellan Börge Björnsson och Anders Larsson. Varken Helge Svensson, Karin Helgesdotter eller Helena Jönsdotter namnges som brukare i denna sammanställning, så deras släktkoppling ska hållas skild från gårdens allmänna historia.","En avskrift ur kyrkoboken berättar att en boskapspest började på Skultagården i oktober 1747 och spreds till Hunnestads och Grimetons pastorat samt Träslövs prästgård. Händelsen hör till gårdens social- och ekonomihistoria, inte som bevis för att direktlinjen bodde där då.","Under 1800-talet brukades gården med hjälp av torpare. Skiftesmaterialet 1839 namnger två änkor som innehavare av var sin halva, och den senare sammanställningen följer övergången till arrendatorer, statare och en större arbetsplats med flera familjer.","Helge Svenssons originalkontrollerade begravningsnotis 1731 ger nu ett direkt belägg för att han var från Skultagården och skulle ligga i gårdens gravställe. Det är den starkaste direkta familjekopplingen till gården, medan exakt boendeform och tidpunkt för flytten från Nils Olsgård fortfarande är öppna."],"timeline":[["1690-05-05","Notis som mycket sannolikt avser en vigsel för Börge Andersson."],["1691-01-18","Kristningsnotis för Börge Anderssons barn i Skultagården."],["1692-11-23","Begravningsnotis som sannolikt avser Lars Jönsson."],["1693-10-29","Mycket sannolik vigselnotis för Anders Larsson."],["1704-07-10","Jöns Polin förekommer sannolikt som fadder/vittne i en kristningsnotis knuten till gården."],["1713-02-22","Ytterligare gårdsnotis, delvis svårläst och ännu inte övertolkad."],["1731-04-25","Helena Jönsdotter anges som piga från Skultagården vid vigseln med Mårten Andersson."],["ca 1630–1640","Sekundärt gårdsblad beskriver flytt av slottsprästens prästgård och Skultagårdens övergång till borgmästarboställe."],["1683","Karl XI uppges ha bekräftat gårdens ställning som borgmästarboställe; originalkälla återstår."],["1729","Landsbeskrivningen återges med Börge Björnsson och Anders Larsson som halvmantalsbrukare."],["1731-04-16","Helge Svensson begravs som mannen från Skultagården och anges ligga i gårdens gravställe."],["1747-10–1748","Boskapspest uppges börja på gården och spridas i området."],["1823","Fyra torp eller lägenheter anges under gården."],["1839","Maria Persdotter och Pernilla Olsdotter står för var sin halva i skiftesbeskrivningen."],["1920","Gården är en arbetsplats för minst sex namngivna arbetare med familjer enligt sammanställningen."],["1933","Carl Larsson flyttar in; Varbergs stad uppges rusta byggnaderna."],["1942","Gården anges omfatta 150 tunnland åker och 10 tunnland utmark."]],"sources":["Skultagård historia.HEIC och Skultagård historia-2.HEIC, lokala maskinskrivna gårdssammanställningar; sekundära källor.","Träslövs död- och begravningsbok 1731, originalsid 225: Helge Svenssons begravning.","Morfars master v125, sammanställning av originalbilder och lokala gårdsblad."],"uncertainties":["Etymologin Skultagården från scultus är en lokal hypotes, inte bevisad namnhistoria.","De administrativa uppgifterna från 1522, 1683 och 1872 samt arealen 1942 behöver kontrolleras mot original.","Helges exakta boende- och brukningsställning på gården före begravningen är fortfarande okänd."]}'::jsonb),updated_at=now() where id='skultagarden';
update public.places set content=replace(content::text,'V89','v125')::jsonb where id='wahlagarden';

