insert into public.places(id,slug,name,area,latitude,longitude,visibility,publish_status,content) values('lille_svensgard','lille-svensgard-lilla-svensgard','Lille Svensgård / Lilla Svensgård','Tvååker',null,null,'public','published','{"id":"lille_svensgard","name":"Lille Svensgård / Lilla Svensgård","area":"Tvååker","aliases":["Lille Svensgård","Lilla Svensgård"],"note":"Bengt Arfvidssons födelsenotis 1768 placerar Arvid Svensson och Elin Bengtsdotter här före familjens senare poster i Munkaskog. Exakt gårdsidentitet och kartläge återstår.","relatedPersonIds":["arvid_svensson","elin_bengtsdotter","bengt_arfvidsson"],"facts":[["Källspår","Födelsenotis för Bengt Arfvidsson 1768"],["Tolkning","Platsväxlingen till Munkaskog 1771 kan avspegla flytt eller en ännu okänd gårds-/hemmankoppling"]],"sources":["Tvååkers födelsebok 1768 enligt syskon-/fadderfilen 2026-07-06; full referens återstår."]}'::jsonb) on conflict(id) do update set content=pg_temp.merge_archive_arrays(public.places.content,excluded.content),updated_at=now();
