insert into public.places(id,slug,name,area,latitude,longitude,visibility,publish_status,content) values('korsberg_klastorp','korsberg','Korsberg','Klastorp',null,null,'public','published','{"id":"korsberg_klastorp","name":"Korsberg","area":"Klastorp","aliases":["Korsberg i Klastorp"],"note":"Modern familjegård i Bengtssonlinjen. Familjeberättelsen placerar Sven Adolf och Gertrud här från omkring 1916 och Axel Harry som brukare från 1954 till 1985.","relatedPersonIds":["sven_adolf_bengtsson","gertrud_persdotter","harry_bengtsson","karin_margit","ingemar_bengtsson"],"facts":[["Källstatus","Handskriven familjeberättelse; fastighetsakter och lagfarter återstår"],["Handel","Gertruds speceriaffär uppges ha flyttats hit"],["Generationsskifte","Axel Harry övertog gården 1954 och Hans Ingemar 1985 enligt familjeberättelsen"]],"story":["Korsberg blev enligt familjeberättelsen både bostad, jordbruksmiljö och plats för Gertruds affär efter Sven Adolfs återkomst från Amerika omkring 1916.","Axel Harry övertog gården 1954 och överlät den till sonen Hans Ingemar 1985, när Axel Harry och Karin flyttade till Valagården."],"timeline":[["ca 1916","Sven Adolf och Gertrud etablerar familjen på Korsberg enligt familjeberättelsen."],["1954","Axel Harry övertar gården."],["1985","Hans Ingemar övertar gården; Axel Harry och Karin flyttar till Valagården."]],"sources":["Mormors handskrivna levnadsberättelse, mottagen 2026-08-31; sekundär familjekälla."]}'::jsonb) on conflict(id) do update set content=pg_temp.merge_archive_arrays(public.places.content,excluded.content),updated_at=now();
