insert into public.places(id,slug,name,area,latitude,longitude,visibility,publish_status,content) values('hansa_klastorp','hansa','Hansa','Klastorp',null,null,'public','published','{"id":"hansa_klastorp","name":"Hansa","area":"Klastorp","aliases":["Hansa i Klastorp"],"note":"Gård eller fastighet som Sven Adolf enligt familjeberättelsen köpte tillsammans med Korsberg efter återkomsten från Amerika. Torsten Verner byggde bilverkstad och bostad här 1954.","relatedPersonIds":["sven_adolf_bengtsson","torsten_verner_bengtsson_1920"],"facts":[["Källstatus","Handskriven familjeberättelse; fastighets- och företagskällor återstår"]],"timeline":[["ca 1916","Köps enligt familjeberättelsen av Sven Adolf efter återkomsten från Amerika."],["1954","Torsten Verner uppges bygga bilverkstad med bostad här."]],"sources":["Mormors handskrivna levnadsberättelse, mottagen 2026-08-31; sekundär familjekälla."]}'::jsonb) on conflict(id) do update set content=pg_temp.merge_archive_arrays(public.places.content,excluded.content),updated_at=now();
