insert into public.people(id,slug,name,born,died,branch,visibility,publish_status,content)
values(
  'ingeborg_paulin_1731',
  'ingeborg-paulin',
  'Ingeborg Paulin',
  null,
  null,
  'mother',
  'public',
  'published',
  '{"name":"Ingeborg Paulin","role":"Fadder i Polin-/Paulin-nätverket","status":"confirmed","branch":"mother","place":"Träslöv","facts":[["Originalbelägg","Namnet H. Ingeborg Paulin förekommer i dopnotiser 1731-06-04 och omkring juli–augusti 1731"],["Annas dop 1732","Återkommer som fadder vid Anna Mårtensdotters dop 1732-04-28"],["Titelns tolkning","H. betyder sannolikt hustru i sammanhanget; maken är inte identifierad"],["Källstatus","Personens namn är starkt originalbelagt, men hennes relation till Jöns Polin är okänd"]],"story":["Ingeborg Paulin återkommer som fadder i minst tre dopnotiser 1731–1732. Det visar att hon var en verklig och återkommande person i Träslövs lokala dopnätverk.","Hennes närvaro vid Anna Mårtensdotters dop binder henne socialt till familjen efter Helena Jönsdotter. Hon kan ha varit släkting, ingift släkting eller nära kontakt, men materialet bevisar inte vilken relation hon hade till Jöns Polin."],"timeline":[["1731-06-04","Står som H. Ingeborg Paulin bland faddrarna vid Annas dop."],["1731-07/08","Förekommer åter som fadder vid ett dop av ett barn Börge; exakt dopdatum är svårläst."],["1732-04-28","Är fadder vid Anna Mårtensdotters dop."]],"parents":[],"children":[],"sources":["Träslövs födelse- och dopbok 1731–1732, originalbilder genomgångna i morfars master v125; fullständiga arkivreferenser återstår."],"uncertainties":["Släktskapet med Jöns Andersson Polin och övriga Polin-/Paulin-personer är en öppen hypotes."]}'::jsonb
)
on conflict(id) do update set content=pg_temp.merge_archive_arrays(public.people.content,excluded.content),updated_at=now();

update public.people set content=pg_temp.merge_archive_arrays(content,
  '{"facts":[["Dop enligt familjeblad","1840-12-04; uppgiften ser ut som en avskrift men originalnotisen är inte kontrollerad"],["Preliminärt lästa dopvittnen","Anders Bengtsson, Johannes Eliasson eller liknande, Gertrud Petersdotter möjligen från Näs samt Karin Bengtsdotter i Träslöv"],["Möjlig farbror bland faddrarna","Anders Bengtsson kan vara Nils Bengtssons bror född 1816, men identiteten är inte bevisad"]],"uncertainties":["Exakt födelsedag, dopdatumet och de antecknade faddrarnas läsning och identitet behöver verifieras i originalnotisen."]}'::jsonb
) where id='bengt_a_nilsson';

update public.people set content=pg_temp.merge_archive_arrays(content,
  '{"facts":[["Faddrar vid dopet 1732","H. Ingeborg Paulin och h. Beata Jönsdotter är starkt lästa; en tredje kvinnlig fadder är oläst. Olof Börjesson och Anders Andersson är relativt sannolika manliga läsningar."],["Fadderkretsens betydelse","Två kvinnor med tydlig koppling till Polinmiljön visar ett nära socialt nätverk, men bevisar inte i sig exakta släktrelationer"]],"story":["Vid Annas dop 1732 omgavs familjen av en fadderkrets med tydlig anknytning till Polin-/Paulinmiljön. Ingeborg Paulin är starkt läst, och Beata Jönsdotter är en stark kandidat till Helenas syster Beata Jönsdotter Polin, men identiteten ska fortsatt hållas källkritiskt öppen."],"timeline":[["1732-04-28","Döps med bland andra Ingeborg Paulin och sannolikt Beata Jönsdotter som faddrar."]],"sources":["Träslövs födelse- och dopbok 1732, originalsid 65; exakt ArkivDigital-volym och bildnummer återstår."],"uncertainties":["Beata Jönsdotters identitet som Helenas syster och flera övriga fadderläsningar behöver ytterligare originalkontroll."]}'::jsonb
) where id='anna_martensdotter_jon_nilsgard';

update public.people set content=pg_temp.merge_archive_arrays(content,
  '{"facts":[["Möjlig levnadsuppgift","Mormors handskrivna blad anger ''dövstum''; uppgiften är inte verifierad i husförhör"]],"story":["Familjeanteckningen kan ge en viktig bild av Olenas livsvillkor, men ordet dövstum ska tills vidare behandlas som en möjlig uppgift och inte som ett fastställt medicinskt faktum."],"sources":["Mormors handskrivna släktanteckningar, mottagna 2026-08-31; sekundär familjekälla."],"uncertainties":["Uppgiften ''dövstum'' behöver prövas mot samtida husförhörslängder."]}'::jsonb
) where id='olena_bengtsdotter_1820';

update public.people set content=pg_temp.merge_archive_arrays(content,
  '{"facts":[["Familjeanteckning","Ordet ''dödförklarad'' står vid Anna Beatas rad i det tydligare familjebladet"],["Källstatus","Betydelsen är okänd och får inte tolkas som ett dödsdatum utan ytterligare källa"]],"story":["Det tydligare handskrivna bladet visar att noteringen dödförklarad hör till Anna Beata och inte till systern Olena. Det är oklart om ordet återger en juridisk åtgärd, en kyrkoboksuppgift eller en privat markering."],"sources":["Mormors handskrivna släktanteckningar, mottagna 2026-08-31; sekundär familjekälla."],"uncertainties":["Noteringen ''dödförklarad'' saknar datum och förklaring och får inte användas som dödsuppgift."]}'::jsonb
) where id='anna_beata_bengtsdotter';

update public.places set content=pg_temp.merge_archive_arrays(content,
  '{"facts":[["Arbetsplats 1920","Johan Julius Severinsson, Johan Emil Persson, Oskar Emil Karlsson och Bernhard Antonsson var statdrängar; Johan Bernt Svensson var jordbruksarbetare och Karl Persson smed. Samtliga anges med sina familjer."],["Arrendekedja","P. J. Hedenbergh 1844–1874, Bengt Andersson ''Skulta-Bengt'' 1874–1887, Adolf Lundqvist och hans sterbhus 1887–1907, Herder Kullberg 1907–1921, Berta Kullberg 1922–1933 samt Carl Larsson från 1933 enligt gårdsbladet"]]}'::jsonb
) where id='skultagarden';

